/* ═══ MY ASSIGNMENTS + USER MENU (family widget — drop-in; built 12 Aug 2026) ═══
   Modular across the family: everything module-specific lives in ASGN_ADAPTER. A module
   supplies (1) openTasks(userId) -> [{id,label,sub,due}] listing that user's incomplete
   assigned tasks in program order, and (2) navigate(taskId). The widget renders the
   user-chip dropdown, the My Assignments modal, and the overview card; it reuses the
   family shell classes (modal-bg/modal, nav-more-*) and adds no CSS of its own. */
var ASGN_ADAPTER={
  openTasks:function(userId){
    var out=[];var assigns=data.assigns||{},co=data.completedSteps||{},due=data.stepDue||{};
    mgSteps().forEach(function(s){
      if((assigns[s.id]||[]).indexOf(userId)<0)return;   /* assigned to this user */
      if(co[s.id])return;                                /* stays listed only until the step is complete */
      out.push({id:s.id,label:s.name,sub:'Phase '+s.ph.id+' \u00b7 '+s.ph.name,due:due[s.id]||null});
    });
    return out;
  },
  navigate:function(taskId){go('step',taskId);}, /* adapter: Governance routes steps via go('step',id) */
  /* assigned tasks whose step is complete — greyed at the list's foot (ruled 12 Aug 2026) */
  doneTasks:function(userId){
    var out=[];var assigns=data.assigns||{},co=data.completedSteps||{};
    mgSteps().forEach(function(s){
      if((assigns[s.id]||[]).indexOf(userId)<0)return;
      if(!co[s.id])return;
      out.push({id:s.id,label:s.name,sub:'Phase '+s.ph.id+' \u00b7 '+s.ph.name,due:null});
    });
    return out;
  }
};
/* Rollout item 58 applied to Governance chrome (21 Aug 2026, ruled from Paul's visual pass probe):
   overlay and chrome toggles repaint their own chrome, never the world. The whole-app render on the
   user-menu chip, its backdrop click-off, the More menu, and sidebar minimize was the full-page flash
   read as a reload. Falls back to render() when the chrome is absent. */
function _userMenuHtml(){if(SAMPLE_MODE)return '<div class="nav-more-backdrop" onclick="closeUserMenu()"></div><div class="nav-more-menu" role="menu"><button class="nav-more-item" role="menuitem" onclick="closeUserMenu();signOut()"><span class="nav-more-ic">&#8594;</span> Sign Out</button></div>'; /* Sweep 4R item 9: the sample tab's account menu */ return (
    '<div class="nav-more-backdrop" onclick="closeUserMenu()"></div>'+
    '<div class="nav-more-menu" role="menu">'+
      '<button class="nav-more-item" role="menuitem" onclick="closeUserMenu();openOrg()"><span class="nav-more-ic"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="7.5" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7z"/></svg></span> Org Profile</button>'+
      '<button class="nav-more-item" role="menuitem" onclick="closeUserMenu();openAssignments()"><span class="nav-more-ic">\u2630</span> View Assignments</button>'+
      '<div class="nav-more-sep"></div>'+
      '<button class="nav-more-item" role="menuitem" onclick="closeUserMenu();signOut()"><span class="nav-more-ic">\u2192</span> Sign Out</button>'+
    '</div>'
  )}
function _navMoreHtml(){var _zz=UI.zoom||1,_zp=Math.round(_zz*100);return (
      '<div class="nav-more-backdrop" onclick="closeNavMore()"></div>'+
      '<div class="nav-more-menu" role="menu">'+
        '<div class="nav-more-zoom">'+
          '<div class="nmz-head"><span class="nmz-lbl">View</span><span class="nmz-val">'+_zp+'%</span></div>'+
          '<div class="nmz-row">'+
            '<button class="nmz-btn" onclick="zoomOut()" title="Zoom out"'+(_zz<=0.5?' disabled':'')+'>\u2212</button>'+
            '<button class="nmz-btn" onclick="zoomIn()" title="Zoom in"'+(_zz>=2?' disabled':'')+'>+</button>'+
            '<button class="nmz-chip" onclick="zoomFit()" title="Fit page to screen">Fit</button>'+
            '<button class="nmz-chip" onclick="zoomReset()" title="Reset to 100%">Reset</button>'+
          '</div>'+
        '</div>'+
        '<div class="nav-more-sep"></div>'+
        
        '<button class="nav-more-item'+(currentPage==='mgmt-hub'?' nav-action-on':'')+'" role="menuitem" onclick="closeNavMore();go(\'mgmt-hub\')"><span class="nav-more-ic">\u25a6</span> Track Program</button>'+ '<button class="nav-more-item'+(currentPage==='reports'?' nav-action-on':'')+'" role="menuitem" onclick="closeNavMore();go(\'reports\')"><span class="nav-more-ic">\u2637</span> Report Manager</button>'+ /* 12 Sep 2026 (Paul's ruling): the report compiler's door */
        (voiceOn()?'<button class="nav-more-item" role="menuitem" onclick="closeNavMore();toggleVoice()"><span class="nav-more-ic">&#9673;</span> Voice</button>':'')+ /* Part 2: a Voice control too, so it shows only while Voice is on */
        (SAMPLE_MODE?'':'<button class="nav-more-item" role="menuitem" onclick="closeNavMore();toggleNotes()"><span class="nav-more-ic">&#9998;</span> Notes <span id="notesCount" class="notes-count">'+((data.notes||[]).length)+'</span></button>')+ /* Part 3.3.8: Notes, with its count, above Org & Team; not in the sample tab */
        (SAMPLE_MODE?'':'<button class="nav-more-item" role="menuitem" onclick="closeNavMore();openOrg()"><span class="nav-more-ic"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="12" cy="7.5" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7z"/></svg></span> Profile</button>')+ /* Part 3: no Org & Team in the sample tab */
        (isAppAdmin&&!SAMPLE_MODE?'<button class="nav-more-item" role="menuitem" onclick="closeNavMore();openAdmin()"><span class="nav-more-ic">&#9638;</span> Admin</button>':'')+
        '<div class="nav-more-sep"></div>'+
        (SAMPLE_MODE?'<button class="nav-more-item" role="menuitem" onclick="closeNavMore();restartSample()"><span class="nav-more-ic">&#8635;</span> Start the sample again</button>'+
          '<button class="nav-more-item" role="menuitem" onclick="closeNavMore();closeSample()"><span class="nav-more-ic">&#10005;</span> Close the sample</button>':
        '<button class="nav-more-item" role="menuitem" onclick="closeNavMore();openChangePassword()"><span class="nav-more-ic">&#9679;</span> Change password</button>'+ /* 5.6 (A.5.11) */
        '<button class="nav-more-item" role="menuitem" onclick="closeNavMore();seedSampleData()"><span class="nav-more-ic">&#8635;</span> Load the seeded example</button>')+ /* Part 3.3.5: the existing sample item stays, and is hidden in the sample tab */
        (SAMPLE_MODE?'':'<button class="nav-more-item" role="menuitem" onclick="closeNavMore();exportState()"><span class="nav-more-ic">&#8595;</span> Export state</button>'+
        '<button class="nav-more-item" role="menuitem" onclick="closeNavMore();importState()"><span class="nav-more-ic">&#8593;</span> Import state</button>')+ /* Sweep 4R item 9 (addendum 5 Oct 2026; amends Part 3): not in the sample tab */
      '</div>')}
function _paintNavMenu(chipSel,flag,htmlFn){var chip=document.querySelector(chipSel);if(!chip)return render();var w=chip.closest('.nav-more-wrap')||chip.parentNode;
chip.classList.toggle('nav-action-on',!!flag);try{chip.setAttribute('aria-expanded',flag?'true':'false')}catch(e){}
var bd=w.querySelector('.nav-more-backdrop'),mn=w.querySelector('.nav-more-menu');
if(flag){if(!mn)w.insertAdjacentHTML('beforeend',htmlFn())}else{if(bd)bd.parentNode&&bd.parentNode.removeChild(bd);if(mn)mn.parentNode&&mn.parentNode.removeChild(mn)}}
function toggleUserMenu(e){if(e&&e.stopPropagation)e.stopPropagation();UI.userMenu=!UI.userMenu;_paintNavMenu('.nav-user-chip',UI.userMenu,_userMenuHtml); /* Governance paints the nav inside render() */}
function closeUserMenu(){if(UI.userMenu){UI.userMenu=false;_paintNavMenu('.nav-user-chip',false,_userMenuHtml); /* Governance paints the nav inside render() */}}
/* Due-dated tasks first (soonest first), undated after in the adapter's program order; stable. */
function asgnOpenTasks(userId){
  var t=ASGN_ADAPTER.openTasks(userId);
  return t.map(function(x,i){x._i=i;return x;}).sort(function(a,b){
    if(a.due&&b.due)return a.due<b.due?-1:a.due>b.due?1:a._i-b._i;
    if(a.due)return -1; if(b.due)return 1; return a._i-b._i;
  });
}
function asgnGo(taskId){closeModal();ASGN_ADAPTER.navigate(taskId);}
function asgnRowHtml(t,isDone,today){
  var overdue=!isDone&&!!(t.due&&t.due<today);
  return '<div onclick="asgnGo(\''+esc(t.id)+'\')" role="link" tabindex="0" style="display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid rgba(var(--fg-rgb),.08);background:rgba(var(--fg-rgb),.03);margin-bottom:8px;cursor:pointer'+(isDone?';opacity:.55':'')+'" title="'+(isDone?'Open this step':'Open this task')+'">'
    +'<div style="flex:1"><div style="font-size:14px;font-weight:600;color:var(--paper)">'+esc(t.label)+'</div>'
    +'<div style="font-family:var(--mono);font-size:10px;color:var(--stone);margin-top:2px">'+esc(t.sub||'')+'</div></div>'
    +(isDone?'<div style="font-family:var(--mono);font-size:11px;color:#1B6B5A;white-space:nowrap">\u2713 Done</div>'
      :(t.due?'<div style="font-family:var(--mono);font-size:11px;color:'+(overdue?'#9B2D3F':'var(--stone)')+';white-space:nowrap">'+(overdue?'Overdue \u00b7 ':'Due ')+esc(fmtDate(t.due))+'</div>':''))
    +'<span style="color:var(--gold);font-size:14px">\u2192</span></div>';
}
function asgnListHtml(userId){
  var open=asgnOpenTasks(userId);
  var done=ASGN_ADAPTER.doneTasks(userId);
  if(!open.length&&!done.length)return '<div style="font-family:var(--serif);font-size:15px;color:var(--stone);font-style:italic;text-align:center;padding:28px 0">No assignments yet. Tasks assigned to you in Track Program appear here.</div>';
  var today=new Date().toISOString().split('T')[0];
  var h='';
  open.forEach(function(t){h+=asgnRowHtml(t,false,today);});
  if(!open.length)h+='<div style="font-family:var(--serif);font-size:15px;color:var(--stone);font-style:italic;text-align:center;padding:14px 0 6px">No open assignments.</div>';
  if(done.length){
    h+='<div style="font-family:var(--mono);font-size:10px;color:var(--stone);letter-spacing:.08em;text-transform:uppercase;margin:14px 0 8px">Completed</div>';
    done.forEach(function(t){h+=asgnRowHtml(t,true,today);});
  }
  return h;
}
function openAssignments(){currentModal='assignments';renderAssignmentsModal();}
function renderAssignmentsModal(){
  var mr=$('modalRoot');if(!mr)return;
  if(currentModal!=='assignments')return; /* never clears another modal's paint */
  var cu=getCurrentUser();
  if(!cu){mr.innerHTML='';currentModal=null;return;}
  var h='<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal">';
  h+='<div style="display:flex;align-items:center;gap:12px;margin-bottom:6px">'+userAv(cu,34)+'<div><h3 class="h-sub-lg" style="margin:0">My Assignments</h3><div style="font-family:var(--mono);font-size:10px;color:var(--stone)">'+esc(cu.name)+(cu.role?' \u00b7 '+esc(cu.role):'')+'</div></div></div>';
  h+='<div style="font-size:13px;color:var(--stone);line-height:1.6;margin-bottom:16px">Tasks assigned to you in Track Program \u2014 click one to go straight to the work. Completed assignments drop to the foot of the list.</div>';
  h+=asgnListHtml(cu.id);
  h+='<div style="display:flex;justify-content:flex-end;margin-top:18px"><button class="btn-gold" onclick="closeModal()">Done</button></div>';
  h+='</div></div>';
  mr.innerHTML=h;
}
/* Renders under the 90-day timeline on the module overview; appears only when the
   signed-in user has at least one open assignment. */
function asgnOverviewCard(){
  var cu=getCurrentUser();if(!cu)return '';
  if(!asgnOpenTasks(cu.id).length)return '';
  return '<div class="mb-6" style="border:1px solid rgba(var(--fg-rgb),.08);padding:20px 24px;background:rgba(var(--fg-rgb),.02)">'
    +'<h3 class="h-sub-md" style="margin:0 0 4px">My Assignments</h3>'
    +'<p class="t-faint-sm" style="margin:0 0 12px">Assigned to you \u2014 open tasks first, completed below.</p>'
    +asgnListHtml(cu.id)
    +'</div>';
}
/* ═══ END MY ASSIGNMENTS + USER MENU ═══ */ /* addendum 217: family widget ported, 19 Aug 2026 */

function adminRenameOrg(id){ if(!isAppAdmin) return; /* Sweep 4R item 10: the app administrator's console checks its caller itself, not only by hiding its button */
  var o=getOrg(id); if(!o)return;
  var nm=prompt('Organization name:', o.name); if(nm===null)return; nm=(nm||'').trim(); if(!nm)return;
  saveOrgs(getOrgs().map(function(x){return x.id===id?Object.assign({},x,{name:nm}):x;}));
  var d=_adminOrgBlob(id); d.enterprise=d.enterprise||{}; d.enterprise.name=nm; _adminPersist(id,d);
  renderAdminModal();
}

function adminOpenOrg(id){ if(!isAppAdmin) return; /* Sweep 4R item 10: the app administrator's console checks its caller itself, not only by hiding its button */
  try{Store.setRemember(null);}catch(e){}
  switchToOrg(id); Auth.setSession((USERS[0]&&USERS[0].id)||null);
  if(!currentUserId){ alert('This organization has no members yet. Add one first.'); switchToOrg(id); renderAdminModal(); return; }
  UI.adminUserEdit=null; closeModal(); render();
}

function adminDeleteOrg(id){ if(!isAppAdmin) return; /* Sweep 4R item 10: the app administrator's console checks its caller itself, not only by hiding its button */
  var o=getOrg(id); if(!o)return;
  if(id===currentOrgId){ alert("You can't delete the organization you're currently in. Switch to another organization first."); return; } // ruled July 9, mirrors adminDeleteUser
  if(getOrgs().length<=1){ alert('You must keep at least one organization.'); return; }
  if(!confirm('Delete "'+o.name+'" and all of its data? This cannot be undone.'))return;
  var wasCurrent=(id===currentOrgId);
  deleteOrgById(id);
  if(wasCurrent){ var others=getOrgs(); if(others.length){ switchToOrg(others[0].id); Auth.setSession((USERS[0]&&USERS[0].id)||null); } }
  renderAdminModal();
}

function adminEditUser(orgId,userId){ if(!isAppAdmin) return; /* Sweep 4R item 10: the app administrator's console checks its caller itself, not only by hiding its button */ UI.adminUserEdit={orgId:orgId,userId:userId}; renderAdminModal(); }

