      var meta=[esc(u.role||''),(u.scope&&u.scope!=='All')?esc(u.scope):''].filter(Boolean).join(' \xb7 ');
      var sub=[esc(u.email||''),esc(u.dept||'')].filter(Boolean).join(' \xb7 ');
