/* ── Chunk 2: automatic decision pinning (Design Draft 5, C-6) ──
   The two invariants, held by construction: (1) pinning is atomic
   — the writer that overwrites a live decision calls pinDecision
   in the same action, never as a separate skippable step; (2) pins
   are immutable, dated, attributed (frozen records). Narrative
   field saves never pin, by design. Historical caller: classifyRisk (retired chunk 12; the band writes via confirmAssessment)
   (reclassification pins the outgoing classification + scores).
   The workbench result band (Chunk 11) becomes the main caller;
   the pinned-history fold and the faint-prior display ride that
   chunk, where the surfaces exist. */
function pinDecision(r,kind,snapshot){if(!r||!snapshot)return;if(!r.history)r.history=[];var u=(typeof getCurrentUser==='function')?getCurrentUser():null;var rec=Object.assign({kind:kind,pinnedAt:Date.now(),pinnedBy:(u&&(u.name||u.username))||''},snapshot);try{rec.content=JSON.parse(JSON.stringify({name:r.name,description:r.description,domain:r.domain||null,assess:r.assess||null}))}catch(e){rec.content=null}try{Object.freeze(rec)}catch(e){}r.history.push(rec)}

/* ── Chunk 1: portfolio derivation core (Design Draft 5, D-1) ──
   Membership DERIVES from the decisions on a card, never from a
   stored status. Legacy fallbacks (riskClasses map, status-string
   reads in the predicates) removed 20 July 2026 — ruled: no
   deployed legacy blobs exist. The inert status field is still
   WRITTEN by legacy writers; full retirement rides the writer
   chunks (11/12). */
function cardClass(r){if(!r)return null;return r.classification||null}
function isArchivedRisk(r){if(!r)return true;if(r.dismissed||r.resolution)return true;return cardClass(r)==='archive'}
function isLiveRisk(r){return !isArchivedRisk(r)}
function inIdentifyBucket(r){return isLiveRisk(r)&&!cardClass(r)&&!(r.selection&&r.selection.decision==='advance')}
function inAssessBucket(r){return isLiveRisk(r)&&!cardClass(r)&&(r.selection&&r.selection.decision==='advance')}
/* ── Chunk 4: composite severity (Q-4 — the rapid composite IS the severity measure) ── */
function compositeOf(r){return((r&&r.litL)||0)+((r&&r.litI)||0)+((r&&r.litT)||0)}
function sevBand(r){var c=compositeOf(r);if(!c)return null;return c>=13?'critical':c>=10?'high':c>=7?'medium':'low'}
function sevBucket(r){var b=sevBand(r);return b==='critical'?'high':b}
function isHighSev(r){var b=sevBand(r);return b==='critical'||b==='high'}
function bandColor(b){return b==='critical'?'#9B2D3F':b==='high'?'#C4553A':b==='medium'?'#D4A017':'#6B7F8D'}
/* ── Chunk 6: Responsible AI flag lifecycle (D-11(1)) — none → potential → confirmed / cleared ── */
function ethStatusOf(r){if(!r)return null;return r.ethStatus||(r.ethicalFlag===true?'potential':null)}
function isEthDesignated(r){var s=ethStatusOf(r);return s==='potential'||s==='confirmed'}
function ethBadge(r){var s=ethStatusOf(r);if(s==='confirmed')return badge('Responsible AI \u00b7 confirmed','#7B4F8A');if(s==='potential')return badge('Responsible AI \u00b7 potential','#9B7FA8');return ''}
function getPortfolios(){
  var out={identify:[],assess:[],manage:[],emergency:[],archived:[]};
  (data.risks||[]).forEach(function(r){
    if(!r)return;
    if(isArchivedRisk(r)){out.archived.push(r);return}
    if(r.escalation){out.emergency.push(r);return}
    if(cardClass(r)){out.manage.push(r);return}
    if(inAssessBucket(r)){out.assess.push(r);return}
    out.identify.push(r);
  });
  return out;
}

