/* -- RESET DATA (Directive 2 Oct 2026, Part 4; replaces the More menu's Reset all data and clearData). Rollout item 68, the reset
   scope law: the organization, its name, its administrators, their passwords and its AI settings stay; every other team member
   is removed, with their sign-in, together with all the program data. The admin console only, and never through switchToOrg:
   resetting another organization's data is not a change of organization for the administrator (S.4). -- */
function getOrgData(id){ return (id===currentOrgId) ? data : (Store.readOrg(id)||govEmptyData()); }
function saveOrgData(id, d){ Store.writeOrg(id, d); if(id===currentOrgId){ data=d; applyTeamRoster(); } }
function withOrgData(id, fn){
  var d=getOrgData(id);
  var r=fn(d);
  if(r && typeof r==='object') d=r;
  saveOrgData(id, d);
  return d;
}
function resetOrgData(id){
  return withOrgData(id, function(d){
    var admins=(Array.isArray(d.roster)?d.roster:[]).filter(function(u){ return u && u.admin===true; });
    var fresh=govEmptyData();
    fresh.roster=admins;
    fresh.settings=d.settings || {aiGuide:false, voice:false};
    fresh.enterprise={name:(d.enterprise&&d.enterprise.name)||((getOrg(id)||{}).name)||''};
    if(d.orgSetup) fresh.orgSetup=true; /* an organization-level flag: a reset does not send its administrators back through setup */
    fresh.startDate=new Date().toISOString().split('T')[0];
    fresh.bf12=true; /* as createOrg starts an organization */
    return fresh;
  });
}
function confirmResetOrg(){ return confirm('Reset all data for this organization? Team members other than administrators are also removed. This cannot be undone.'); }
/* A viewer of that organization whom the reset removed is replaced by its first administrator. Only someone who WAS signed in:
   with nobody signed in (the full-screen console), a reset must not sign anyone in (7 Oct 2026). */
function afterResetOrg(id, viewer){ if(viewer && id===currentOrgId && !getCurrentUser()) Auth.setSession((USERS[0]&&USERS[0].id)||null); }
function adminResetOrg(id){ /* the Admin panel */
  if(!isAppAdmin || !getOrg(id)) return;
  if(!confirmResetOrg()) return;
  var viewer=(id===currentOrgId) ? currentUserId : null;
  resetOrgData(id); afterResetOrg(id, viewer);
  render(); renderAdminModal();
}
function adminConsoleReset(id){ /* the full-screen admin console */
  if(!isAppAdmin || !getOrg(id)) return;
  if(!confirmResetOrg()) return;
  var viewer=(id===currentOrgId) ? currentUserId : null;
  resetOrgData(id); afterResetOrg(id, viewer);
  UI.entry={step:'admin'}; render();
}

