// === STEP ===
function renderStep(){
if(!currentStep)return renderModuleOverview();
var ph=currentPhase;if(!ph)return renderModuleOverview();
var stepObj=null;for(var j=0;j<ph.steps.length;j++){if(ph.steps[j].id===currentStep){stepObj=ph.steps[j];break}}
if(!stepObj)return renderModuleOverview();

var h='<div class="content-area"><div class="content-inner">';
// Breadcrumb (family register, Rollout 27)
h+='<div class="u-79840ab">';
var _sbk=pfBackBtn();if(_sbk)h+=_sbk+' ';/* Framework Overview button removed from step headers 31 Jul 2026 by ruling \u2014 the back chip and sidebar are the navigators, donor form. */
h+='<div class="u-463b2e1">Phase '+ph.id+' · '+ph.name+' <span class="t-gold">/ '+stepObj.name+'</span></div>';
h+='</div>';

// NIST AI RMF alignment badges
h+=nistBadges(currentStep);
h+=stepAssignBar(currentStep);

// Step nav
h+='<div class="step-nav" style="display:grid;grid-template-columns:repeat('+ph.steps.length+',minmax(0,1fr))">';/* item 58: N equal boxes, one row, no empty tail \u2014 the second word wraps inside its box */
for(var j=0;j<ph.steps.length;j++){var s=ph.steps[j];var done=isStepDone(s.id);
h+='<button class="step-nav-btn'+(currentStep===s.id?' active':'')+(done?' done':'')+'" onclick="go(\'step\',\''+s.id+'\')">'+s.name+'</button>'}
h+='</div>';

// Step content (module renderer handles headers, context, milestones)
h+=renderStepContent(currentStep);

// Milestone reward card + phase wrap-up on the phase-last step (item 52)
h+=milestone(currentStep)+phaseWrapCard(currentStep);

// Navigation
var allSteps=[];for(var i=0;i<PH.length;i++)for(var j=0;j<PH[i].steps.length;j++)allSteps.push(PH[i].steps[j]);
var curIdx=allSteps.findIndex(function(s){return s.id===currentStep});
h+='<div style="display:flex;justify-content:space-between;margin-top:40px;padding-top:24px;border-top:1px solid var(--rule)">';
if(curIdx>0){var prev=allSteps[curIdx-1];h+='<button class="btn-ghost" onclick="go(\'step\',\''+prev.id+'\')">← '+prev.name+'</button>'}else{h+='<div></div>'}
if(curIdx<allSteps.length-1){var next=allSteps[curIdx+1];h+='<button class="btn-gold" onclick="go(\'step\',\''+next.id+'\')">'+next.name+' →</button>'}
h+='</div>';

h+='</div></div>';
return h;
}

