// UI state for module (sidebar, expand toggles, etc.)
var UI={v:'home',prev:null,sb:true,theme:'light',zoom:1,navMore:false,showEx:{},expanded:{},editSys:null,editRisk:null,showSysForm:false,showRiskForm:false,activeRisk:null,activeView:null,triageActive:null,abSec:'1.1a'};
var UI_PRISTINE = JSON.stringify(UI); /* the session's starting state, for sealSession */
/* ── Theme + zoom + More menu (ported from the innovation app).
   Light is the default; a saved 'dark' pref is honored. index.html
   pre-paints the attribute before first render. ── */
(function initPrefs(){
  try{ UI.theme = (Store.getPref('theme')==='dark') ? 'dark' : 'light'; }catch(e){ UI.theme='light'; }
  try{ var z=parseFloat(Store.getPref('zoom')); if(!isNaN(z)) UI.zoom=Math.max(0.5,Math.min(2,z)); }catch(e){}
  try{ document.documentElement.setAttribute('data-theme', UI.theme); }catch(e){}
})();
function setTheme(t){ UI.theme=(t==='dark')?'dark':'light';
  try{ Store.setPref('theme', UI.theme); }catch(e){}
  try{ document.documentElement.setAttribute('data-theme', UI.theme); }catch(e){}
  render(); }
function toggleTheme(){ setTheme(UI.theme==='dark'?'light':'dark'); }
function setZoom(v){ var z=Math.max(0.5,Math.min(2,Math.round(v*100)/100)); UI.zoom=z;
  try{ Store.setPref('zoom', z); }catch(e){} render(); }
function zoomIn(){ setZoom((UI.zoom||1)+0.1); }
function zoomOut(){ setZoom((UI.zoom||1)-0.1); }
function zoomReset(){ setZoom(1); }

/* ── zoomFit / export / import (ported from the innovation app) ── */
function zoomFit(){
  var w = document.getElementById('zoomWrap');
  if(!w) return setZoom(1);
  var prevZoom = w.style.zoom || '';
  w.style.zoom = 1;
  var naturalH = w.scrollHeight;
  var viewportH = (window.innerHeight || 800) - 120;
  if(prevZoom) w.style.zoom = prevZoom;
  var fitScale = naturalH > 0 ? Math.max(0.5, Math.min(1, viewportH / naturalH)) : 1;
  setZoom(fitScale);
}
function exportState(){
  try{
    var payload={app:'nextchapter-governance',type:'governance-state',schema:'gov-v3',exportedAt:new Date().toISOString(),data:data};
    var blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a');a.href=url;
    a.download='governance-state-'+new Date().toISOString().split('T')[0]+'.json';
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    setTimeout(function(){URL.revokeObjectURL(url);},1500);
  }catch(e){alert('Export failed: '+((e&&e.message)||e));}
}
function importState(){
  var inp=document.createElement('input');inp.type='file';inp.accept='application/json,.json';
  inp.onchange=function(){
    var f=inp.files&&inp.files[0];if(!f)return;
    var r=new FileReader();
    r.onload=function(){applyImportedState(String(r.result));};
    r.onerror=function(){alert('Could not read that file.');};
    r.readAsText(f);
  };
  inp.click();
}
function applyImportedState(text){
  var parsed;
  try{parsed=JSON.parse(text);}catch(e){alert('That file is not valid JSON.');return;}
  var d=(parsed&&typeof parsed==='object'&&parsed.data)?parsed.data:parsed;
  if(!d||typeof d!=='object'||(d.completedSteps===undefined&&d.risks===undefined&&d.systems===undefined)){alert('That does not look like a Governance state file.');return;}
  if(parsed&&parsed.schema&&parsed.schema!=='gov-v3'){if(!confirm('This file was exported from a different schema ('+parsed.schema+'). Import anyway?'))return;}
  if(!confirm('Importing replaces your current progress. Continue?'))return;
  data=d; saveData(); UI.activeView=null; go('home');
}
function toggleNavMore(e){ if(e&&e.stopPropagation)e.stopPropagation(); UI.navMore=!UI.navMore; _paintNavMenu('.nav-more-wrap button[title="More"]',UI.navMore,_navMoreHtml); }
function closeNavMore(){ if(UI.navMore){ UI.navMore=false; _paintNavMenu('.nav-more-wrap button[title="More"]',false,_navMoreHtml); } }


