function planArrivedAt(r){var pins=r.history||[];var t=0;for(var i=0;i<pins.length;i++){if((pins[i].kind==='reclassification'||pins[i].kind==='de-escalation')&&pins[i].pinnedAt>t)t=pins[i].pinnedAt}return t}
