function reviveRisk(id){var r=_wbFind(id);if(!r)return;if(lockBlocked('risks::'+id))return;if(!isArchivedRisk(r))return;if(!confirm('Revive \u201c'+r.name+'\u201d? It returns to the portfolio its remaining decisions imply \u2014 the archived state pins to the card, superseded, never deleted.'))return;var snap={};if(r.dismissed)snap.dismissed=r.dismissed;if(r.resolution)snap.resolution=r.resolution;if(r.classification==='archive')snap.classification='archive';pinDecision(r,'revive',snap);delete r.dismissed;delete r.resolution;if(r.classification==='archive')r.classification=null;saveData();render()}
