/* ── 16 Aug 2026 night, surface-repair directive (Paul's approved drawing): symmetric two-level cards.
   The management plan card holds Plan name, Owner and Plan type (its Edit opens just those; Remove plan
   lives inside the open form). Actions are self-saving cards parallel to indicators: Add action opens
   a form, Save commits directly, Edit reopens it, Remove action lives inside the form. The done
   checkboxes are working controls on the read rows and commit on click, definition-independent. ── */
var _cardSeq=0;
function _mgStashCur(){if(UI.mgOpen&&UI.mgCards&&(UI.mgCards.plan||UI.mgCards.act||UI.mgCards.em)){if(!UI.mgStash)UI.mgStash={};UI.mgStash[UI.mgOpen]={cards:UI.mgCards}}}
function openMgLanding(id){if(UI.mgOpen===id){_mgStashCur();UI.mgOpen=null;UI.mgCards=null;render();return}
_mgStashCur();UI.mgOpen=id;var st=(UI.mgStash||{})[id];
if(st){UI.mgCards=st.cards||{plan:null,act:null,em:null};delete UI.mgStash[id];render();return}
UI.mgCards={plan:null,act:null,em:null};render()}
function _mgHolder(r){if(!r.mgmtPlan)r.mgmtPlan={plans:[],emergencies:[],notes:[]};if(!Array.isArray(r.mgmtPlan.plans))r.mgmtPlan.plans=[];if(!r.mgmtPlan.notes)r.mgmtPlan.notes=[];if(!r.mgmtPlan.emergencies)r.mgmtPlan.emergencies=[];return r.mgmtPlan}
