var same=String(d.action||'')===String(a.action||'')&&String(d.description||'')===String(a.description||'')&&String(d.owner||'')===String(a.owner||'')&&String(d.timeframe||'')===String(a.timeframe||'')&&((d.recur==='periodic')===(!!a.recur));/* the composer stores the select string; the record stores the boolean (corrected 22 Aug 2026) */
