function ttFreqKey(f){var k=String(f||'').replace(/\s+/g,' ').replace(/^\s+|\s+$/g,'').toLowerCase();if(k==='every two weeks'||k==='bi-weekly'||k==='fortnightly')k='biweekly';return MN_PERIOD.hasOwnProperty(k)?k:''}
