/* \u2500\u2500 Chunk 21: reclassify control (M-6) \u2014 binary Manage\u2194Monitor; Archive rides the workbench (M-7) \u2500\u2500 */
function reclassifyRisk(id){var r=_wbFind(id);if(!r)return;if(lockBlocked('risks::'+id))return;var cur=cardClass(r);if(!cur||cur==='archive')return;
var target=(cur==='manage')?'monitor':'manage';var tl=(target==='manage')?'Manage':'Monitor';
var reason=prompt('Reclassify \u201c'+r.name+'\u201d to '+tl+'? One-line reason \u2014 required; the outgoing classification pins to the card:');
if(reason===null)return;reason=(''+reason).replace(/^\s+|\s+$/g,'');
if(!reason){alert('A reason is required \u2014 reclassification is a decision.');return}
pinDecision(r,'reclassification',{classification:cur,reason:reason});
r.classification=target;UI.mgOpen=null;UI.mnOpen=null;UI.mgCards=null;UI.mnCards=null;UI.mnScalar=null;
saveData();render()}
function goModule(v){
if(v==='home')go('overview');
else if(v.match(/^\d+\.\d/))go('step',v);
else if(v.indexOf('out-')===0)go('outcome',v);
else if(v.indexOf('phase-')===0){var pid=v.split('-')[1];go('phase',pid)}
else if(v==='5.1')go('phase5');
else if(v.indexOf('pf-')===0)go('portfolio',v.slice(3));
else go('overview');
}

