// === CLASSIFICATION HELPERS ===
function getSignificance(l,i){if(!l||!i||l===1||i===1)return'low';if(l>=4&&i>=4)return'critical';if((l>=4&&i>=2)||(l>=2&&i>=4))return'high';if(l>=2&&i>=2)return'medium';return'low'}
function sigLabel(s){return{critical:'Critical',high:'High',medium:'Medium',low:'Low'}[s]||'\u2014'}
function sigColor(s){return{critical:'#9B2D3F',high:'#D4A017',medium:'#3A8B8B',low:'#6B7F8D'}[s]||'var(--text-faint)'}
/* getResponse retired (chunk 14) with the dashboard likert flow. */
function respLabel(r){return{manage:'Manage',monitor:'Monitor',archive:'Archive'}[r]||'\u2014'}
function respColor(r){return{manage:'#9B2D3F',monitor:'#3A8B8B',archive:'#6B7F8D'}[r]||'var(--text-faint)'}
/* explainClassification retired (chunk 14) with the dashboard likert flow. */

// Step completion
function isStepDone(sid){
var co=data.completedSteps||{};var comp=data.completed||{};
if(sid==='1.1')return!!(co['1.1']);/* R-12/R-13 (Paul, 21 July): the stamp is the state; the step button gates on all five chips */
if(sid==='2.2')return!!(co['2.2']);/* R-12: same grammar \u2014 stamp-based, button gated on the four chips */
if(sid==='1.2')return!!(co['1.2']);/* item 55: stamp-based since item 46 gave the step its button \u2014 derived doneness showed Complete the moment a system existed */
if(sid==='1.3')return!!(co['1.3']);/* item 55: same */
if(sid==='1.4')return!!(co['1.4']);
if(sid==='5.1'||sid==='5.2'||sid==='5.3'||sid==='5.4')return false;
return!!(co[sid]||comp[sid])}
// === SHARED UI BUILDERS ===
function badge(text,color){return'<span class="bg" style="background:'+color+'18;color:'+color+'">'+esc(text)+'</span>'}
function card(inner,style,attrs){return'<div class="cd"'+(attrs?' '+attrs:'')+(style?' style="'+style+'"':'')+'>'+inner+'</div>'}
function xpandClick(ev,key,val){var t=ev&&ev.target,c=ev&&ev.currentTarget;
while(t&&t!==c){if(/^(INPUT|SELECT|TEXTAREA|BUTTON|A|LABEL)$/.test(t.tagName||'')||(t.getAttribute&&t.getAttribute('onclick')))return;t=t.parentNode}
try{if(typeof getSelection==='function'&&String(getSelection()))return}catch(e){}
if(val===false&&c&&c.querySelector){var hd=c.querySelector('.xh');if(hd&&hd.getBoundingClientRect&&ev.clientY!=null){var r=hd.getBoundingClientRect();if(ev.clientY>r.bottom+8)return}}
UI.expanded[key]=val;render()}
function regRowClick(ev,id){var t=ev&&ev.target,c=ev&&ev.currentTarget;while(t&&t!==c){if(/^(INPUT|SELECT|TEXTAREA|BUTTON|A|LABEL)$/.test(t.tagName||'')||(t.getAttribute&&t.getAttribute('onclick')))return;t=t.parentNode}try{if(typeof getSelection==='function'&&String(getSelection()))return}catch(e){}UI.regOpen=UI.regOpen===id?null:id;render()}
function xpandAttr(key,open){return 'onclick="xpandClick(event,\''+key+'\','+(!open)+')"'}
function _btnKeep(style){var out=[];String(style||'').split(';').forEach(function(d){d=d.trim();if(!d)return;var k=d.split(':')[0].trim();if(k==='font-size'||k==='padding'||k==='border-radius'||k==='font-weight')return;out.push(d)});return out.join(';')}
/* Family button register (A-1, 22 July): .btn base + bp (filled) / bs (outline) modifiers — the Pipeline's own in-surface grammar. Legacy per-call size overrides are stripped; margins/flex/explicit colors survive. */
function btn(label,onclick,color,style,disabled){var st=_btnKeep(style);return'<button class="btn bp"'+(disabled?' disabled':'')+' onclick="'+esc(onclick||'')+'" style="background:'+(color||'var(--gold)')+';'+(disabled?'opacity:.5;cursor:not-allowed;':'')+st+'">'+label+'</button>'}
function btnS(label,onclick,color,style){var st=_btnKeep(style);var c=color||'var(--gold-text)';return'<button class="btn bs" onclick="'+esc(onclick||'')+'" style="color:'+c+';border-color:'+c+';'+st+'">'+label+'</button>'}
function btnAdd(label,onclick,variant,style){var st=_btnKeep(style);return'<button class="btn add'+(variant?' '+variant:'')+'" onclick="'+esc(onclick||'')+'" style="'+st+'">'+label+'</button>'}/* copy-pass button audit, 21 Aug 2026, ruled by Paul: one family Add form */
function btnG(label,onclick,style){var st=_btnKeep(style);return'<button class="btn bs" onclick="'+esc(onclick||'')+'" style="color:var(--text-body);border-color:rgba(var(--fg-rgb),.25);'+(st||'')+'">'+label+'</button>'}
function ta(label,id,v,ph,rows,ro){var _g=(!ro&&/\*/.test(label))?' gate-field':'';var _lbl=ro?String(label).replace(/\s*\*\s*$/,''):label;var _hnd=ro?'':' oninput="this.style.height=\'auto\';this.style.height=this.scrollHeight+\'px\';gateRepaint()"';return'<div class="mb-4"><label class="form-label">'+esc(_lbl)+'</label><textarea id="'+id+'" rows="'+(rows||3)+'" class="ta-helper'+_g+'"'+_hnd+(ro?' readonly':'')+' placeholder="'+esc(ph||'')+'">'+esc(v||'')+'</textarea></div>'}
function inp(label,id,val,ph,type){var _g=(/\*/.test(label))?' gate-field':'';return'<div class="mb-4"><label class="form-label">'+esc(label)+'</label><input type="'+(type||'text')+'" id="'+id+'" class="inp-helper'+_g+'" oninput="gateRepaint()" value="'+esc(val||'')+'" placeholder="'+esc(ph||'')+'"/></div>'}
function sel(label,id,v,opts,gloss,extraChange){var h='<div class="mb-4"><label class="form-label">'+esc(label)+'</label>'+(gloss?'<p class="t-faint-sm" style="margin:-2px 0 8px">'+esc(gloss)+'</p>':'')+'<select id="'+id+'" class="sel-helper'+(/\*/.test(label)?' gate-field':'')+'" onchange="gateRepaint()'+(extraChange?';'+extraChange:'')+'">';opts.forEach(function(o){h+='<option value="'+esc(o.v)+'"'+(v===o.v?' selected':'')+'>'+esc(o.l)+'</option>'});return h+'</select></div>'}
function likert(label,id,val,lo,hi,help){var h='<div class="mb-5"><label class="form-label-md">'+esc(label)+'</label>'+(help?'<p style="font-size:13px;color:var(--paper);margin:-4px 0 8px;line-height:1.5">'+esc(help)+'</p>':'')+'<div class="flx-center gap-2'+(/\*/.test(label)?' gate-field gate-likert':'')+'"><span class="lk-cap">'+esc(lo)+'</span>';for(var n=1;n<=5;n++){var s=val===n;h+='<button onclick="likSet(\''+id+'\','+n+')" class="lk-btn'+(s?' sel':'')+'">'+n+'</button>'}return h+'<span class="lk-cap lk-cap-r">'+esc(hi)+'</span></div></div>'}
function likSet(path,n){var parts=path.split('.');if(parts.length===2){if(!data[parts[0]])data[parts[0]]={};data[parts[0]][parts[1]]=n}else if(parts.length===1)data[parts[0]]=n;saveData();render()}
