function saveRisk(){if(UI.editRisk&&lockBlocked('risks::'+UI.editRisk))return;UI.riskDraft=null;var _prev=UI.editRisk?(data.risks||[]).find(function(x){return x.id===UI.editRisk}):null;var r={id:UI.editRisk||uid(),loggedBy:_prev?(_prev.loggedBy||''):(((typeof getCurrentUser==='function'&&getCurrentUser())||{}).name||''),loggedAt:_prev?(_prev.loggedAt||''):new Date().toISOString().split('T')[0],name:val('rf_name'),description:val('rf_description'),category:val('rf_category'),source:UI.riskTrack||'internal',systemId:val('rf_systemId')||null,ethicalFlag:UI.riskEthFlag==='true'?true:UI.riskEthFlag==='false'?false:null,ethicalDesc:val('rf_ethicalDesc')||'',status:'identified'};if(!r.name)return;if(!data.risks)data.risks=[];if(UI.editRisk){data.risks=data.risks.map(function(x){return x.id===UI.editRisk?Object.assign(x,r):x})}else{data.risks.push(r)}UI.showRiskForm=false;UI.editRisk=null;saveData();render()}
