/* Regime standards PDFs (item 44). Deployed builds provide window.GovDocStore, the server
   document adapter: { upload: function(file) -> Promise<{url}> , remove: function(url) -> Promise (best-effort) }.
   When the adapter is present, uploads go to the server and the regime stores {name,size,url}.
   Without it (local/dev), the file is kept inline as a data URL — no size cap by ruling (22 July):
   local-browser limits do not apply to the deployment target. */
function regimeDocChip(g){if(!g||!g.doc)return'';return '<button class="btn-ghost pad-chip-sm" style="margin-bottom:0" onclick="viewRegimeDoc(\''+g.id+'\')" title="Open the uploaded standards PDF">\u2b07 '+esc(g.doc.name)+'</button>'}
function regimeDocControl(g){if(g.doc)return '<div style="display:flex;align-items:center;gap:8px;margin:6px 0 10px">'+regimeDocChip(g)+btnG('\u00d7 Remove','removeRegimeDoc(\''+g.id+'\')')+'</div>';
return '<div style="margin:6px 0 10px"><label class="btn-ghost pad-chip-sm" style="cursor:pointer;margin-bottom:0">\u2b06 Upload documents<input type="file" accept="application/pdf,.doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" style="display:none" onchange="regimeDocPicked(this,\''+g.id+'\')"/></label></div>'}
function _regimeDocRead(f,done){if(!f)return;if(['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'].indexOf(f.type)<0){alert('PDF or Word documents only.');return}
if(window.GovDocStore&&window.GovDocStore.upload){window.GovDocStore.upload(f).then(function(res){done({name:f.name,size:f.size,url:res&&res.url})}).catch(function(){alert('The upload to the server failed. Try again.')});return}
var r=new FileReader();r.onload=function(){done({name:f.name,size:f.size,data:r.result})};r.readAsDataURL(f)}
function regimeDocPicked(inp,gid){_regimeDocRead(inp.files&&inp.files[0],function(doc){var g=(data.regimes||[]).find(function(x){return x.id===gid});if(!g)return;g.doc=doc;saveData();render()})}
function regimeDocPickedNew(inp){_regimeDocRead(inp.files&&inp.files[0],function(doc){UI.pendingDoc=doc;render()})}
/* addendum 160 (15 Aug 2026, ruled): the system specification \u2014 a reference field plus the upload, riding the regime document adapter */
function sysSpecDocControl(s){if(s.specDoc)return '<div style="display:flex;align-items:center;gap:8px;margin:6px 0 10px"><button class="btn-ghost pad-chip-sm" style="margin-bottom:0" onclick="viewSysSpecDoc(\''+s.id+'\')" title="Open the uploaded specification">\u2b07 '+esc(s.specDoc.name)+'</button>'+btnG('\u00d7 Remove','removeSysSpecDoc(\''+s.id+'\')')+'</div>';
return '<div style="margin:6px 0 10px"><label class="btn-ghost pad-chip-sm" style="cursor:pointer;margin-bottom:0">\u2b06 Upload the specification<input type="file" accept="application/pdf,.doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" style="display:none" onchange="sysSpecDocPicked(this,\''+s.id+'\')"/></label></div>'}
function sysSpecDocPicked(inp,sid){_regimeDocRead(inp.files&&inp.files[0],function(doc){var s=(data.systems||[]).find(function(x){return x.id===sid});if(!s)return;s.specDoc=doc;saveData();render()})}
function viewSysSpecDoc(sid){var s=(data.systems||[]).find(function(x){return x.id===sid});if(!s||!s.specDoc)return;if(s.specDoc.url){window.open(s.specDoc.url,'_blank');return}try{var b64=String(s.specDoc.data).split(',')[1];var bin=atob(b64);var arr=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);var url=URL.createObjectURL(new Blob([arr],{type:'application/pdf'}));window.open(url,'_blank')}catch(e){alert('Could not open the document.')}}
function removeSysSpecDoc(sid){if(lockBlocked('systems::'+sid))return;var s=(data.systems||[]).find(function(x){return x.id===sid});if(!s)return;if(!confirm('Remove the uploaded specification from this system?'))return;var d=s.specDoc;s.specDoc=null;saveData();render();if(d&&d.url&&window.GovDocStore&&window.GovDocStore.remove){try{window.GovDocStore.remove(d.url)}catch(e){}}}
function viewRegimeDoc(gid){var g=(data.regimes||[]).find(function(x){return x.id===gid});if(!g||!g.doc)return;if(g.doc.url){window.open(g.doc.url,'_blank');return}try{var b64=String(g.doc.data).split(',')[1];var bin=atob(b64);var arr=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);var url=URL.createObjectURL(new Blob([arr],{type:'application/pdf'}));window.open(url,'_blank')}catch(e){alert('Could not open the PDF.')}}
function removeRegimeDoc(gid){if(lockBlocked('regimes::'+gid))return;var g=(data.regimes||[]).find(function(x){return x.id===gid});if(!g)return;if(!confirm('Remove the uploaded document from this regime?'))return;var d=g.doc;g.doc=null;saveData();render();if(d&&d.url&&window.GovDocStore&&window.GovDocStore.remove){try{window.GovDocStore.remove(d.url)}catch(e){}}}
function addRegime(){var nm=String(val('ng_name')||'').trim();if(!nm){alert('The regime needs a name.');return}if(!data.regimes)data.regimes=[];
data.regimes.push({id:'reg-'+Math.random().toString(36).substr(2,9),name:nm,type:val('ng_type')||'other',scoping:null,systems:'all',summary:val('ng_summary'),link:val('ng_link'),doc:UI.pendingDoc||null,obligations:[],owner:val('ng_owner'),revisit:''});
UI.regAdd=false;UI.pendingDoc=null;saveData();render()}
function savePotential(gid){var g=(data.regimes||[]).find(function(x){return x.id===gid});if(!g)return;var e;e=document.getElementById('pe_name');if(e&&e.value.trim())g.name=e.value.trim();e=document.getElementById('pe_type');if(e)g.type=e.value;e=document.getElementById('pe_summary');if(e)g.summary=e.value;e=document.getElementById('pe_link');if(e)g.link=e.value;saveData();UI.regOpen=null;render()}/* item 57: element-guarded per \u00a77A */
function removeRegime(id){if(lockBlocked('regimes::'+id))return;var g=(data.regimes||[]).find(function(x){return x.id===id});if(!g||(g.scoping&&g.scoping.judgment)||(g.obligations||[]).length)return;/* mistake-erasure only \u2014 judged or itemized regimes stay */
if(!confirm('Remove \u201c'+g.name+'\u201d from the register?'))return;data.regimes=(data.regimes||[]).filter(function(x){return x.id!==id});UI.regOpen=null;saveData();render()}
function harvestRegime(g){var _e;/* item 50: per-field guards \u2014 the 2.4 scoping rows render without these fields, and a blind harvest would blank them */
_e=document.getElementById('rg_summary');if(_e)g.summary=_e.value;
_e=document.getElementById('rg_link');if(_e)g.link=_e.value;
_e=document.getElementById('rg_owner');if(_e)g.owner=_e.value;
_e=document.getElementById('rg_revisit');if(_e)g.revisit=_e.value;
var allEl=document.getElementById('rg_sys_all');if(allEl){if(allEl.checked)g.systems='all';else{var ids=[];var els=document.querySelectorAll('.rg-sys');for(var i=0;i<els.length;i++)if(els[i].checked)ids.push(els[i].getAttribute('data-sid'));g.systems=ids}}}
function setScoping(id){var g=(data.regimes||[]).find(function(x){return x.id===id});if(!g)return;
var j=val('rg_judgment');if(!j){alert('Pick a judgment \u2014 applies, does not apply, or investigate.');return}
var reason=String(val('rg_reason')||'').trim();if(!reason){alert('The scoping judgment needs its reason \u2014 dated, attributed, on the record.');return}
harvestRegime(g);var u=(typeof getCurrentUser==='function')?getCurrentUser():null;
g.scoping={judgment:j,reason:reason,by:(u&&(u.name||u.username))||'',at:Date.now()};
regimePin(g,'scoping',{judgment:j,reason:reason});/* C-6: scoping writes pin */
saveData();UI.regOpen=null;/* item 60: recording the judgment closes the row wherever it lands */render()}
function addObligation(id){var g=(data.regimes||[]).find(function(x){return x.id===id});if(!g)return;if(lockBlocked('regimes::'+id))return;harvestRegime(g);saveObligations(g);
if(!g.obligations)g.obligations=[];g.obligations.push({id:'ob-'+Math.random().toString(36).substr(2,9),name:'',statement:'',evidence:'',status:'notstarted'});UI.expanded['ob_'+g.id+'_'+(g.obligations.length-1)]=true;saveData();render()}
function saveObligations(g){var obs=g.obligations||[];var u=(typeof getCurrentUser==='function')?getCurrentUser():null;
for(var i=0;i<obs.length;i++){if(!document.getElementById('ob_'+i+'_statement'))continue;
obs[i].name=val('ob_'+i+'_name');obs[i].statement=val('ob_'+i+'_statement');obs[i].evidence=val('ob_'+i+'_evidence');
var ns=val('ob_'+i+'_status');if(ns&&ns!==obs[i].status){var from=obs[i].status;obs[i].status=ns;obs[i].by=(u&&(u.name||u.username))||'';obs[i].at=Date.now();
regimePin(g,'obligation-status',{obId:obs[i].id,from:from,to:ns});/* C-6: status writes pin */}}}
function saveRegime(id){var g=(data.regimes||[]).find(function(x){return x.id===id});if(!g)return;harvestRegime(g);saveObligations(g);saveData();render()}
function buildRegimeCSV(){var esc2=function(v){v=String(v==null?'':v);return '"'+v.replace(/"/g,'""')+'"'};
var rows=[['Regime','Type','Scoping','Reason','Owner','Systems','Obligation','Status','Evidence'].join(',')];
(data.regimes||[]).forEach(function(g){var sysStr=g.systems==='all'?'All systems':((g.systems||[]).map(function(id){var s=(data.systems||[]).find(function(x){return x.id===id});return s?s.name:id}).join('; '));
var base=[esc2(g.name),esc2(g.type),esc2((g.scoping||{}).judgment||'unscoped'),esc2((g.scoping||{}).reason),esc2(g.owner),esc2(sysStr)];
var obs=g.obligations||[];
if(!obs.length)rows.push(base.concat([esc2(''),esc2(''),esc2('')]).join(','));
else obs.forEach(function(o){rows.push(base.concat([esc2(o.statement),esc2(o.status),esc2(o.evidence)]).join(','))})});
return rows.join('\n')}
function exportRegimeCSV(){try{var csv=buildRegimeCSV();var blob=new Blob([csv],{type:'text/csv'});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='regime-register.csv';document.body.appendChild(a);a.click();document.body.removeChild(a)}catch(e){if(window.console&&console.error)console.error('export failed',e)}}

function saveDR(){if(!confirmSectionDone('1.1d'))return;if(!data.decisionRights)data.decisionRights={};['approveDeployment','requireReview','haltDeployment','reallocateResources','gaps'].forEach(function(f){data.decisionRights[f]=val('dr_'+f)});if(!data.completed)data.completed={};data.completed['1.1d']=true;UI.abSec='1.1e';saveData();render();scrollToSection()}
// === PHASE 2 STEPS ===
/* Shared register body: 2.1 and the dashboard spine render the same catalog (D-11(6)) */
function principleRegisterBody(){var ef=data.ethicalFramework||{};var prs=ef.principles||[];
/* round 37 (10 Aug 2026, Paul's design): domains as sections, one card per principle \u2014 a bar carrying the sentence, expanding to details and the breach line, with the donor read-then-Edit grammar. Shared verbatim by 2.1 and the Responsible AI Overview. */
var f=function(l,v){return v?'<div style="margin-top:8px"><div class="u-b25d981" style="margin-bottom:3px">'+l+'</div><div class="fs-13" style="color:var(--text-muted);line-height:1.55">'+esc(v)+'</div></div>':''};
var h='<h3 class="h-section" style="font-size:18px;margin:0 0 8px;color:var(--t-brown)">Register of Responsible AI Principles</h3><p style="font-size:13px;color:var(--text-faint);margin-bottom:12px">Write principles as commitments an outsider could hold you to, and give each a breach line: what, concretely, would violate it? Start from the five classic topics \u2014 fairness, human oversight, workforce impact, societal effects, transparency \u2014 and go beyond them where your organization demands it.</p>';
var doms=ethDomains();/* round 38 (Paul's ruling): no Unassigned section \u2014 the add flow always assigns a domain; a legacy blank-domain principle would not render here and still reaches the confirmation test */
var barFor=function(pr){var k='prx_'+pr.id;var open=!!UI.expanded[k];
if(UI.prEdit&&UI.prEdit[pr.id]){return card('<input id="pr_e_'+pr.id+'_sentence" value="'+esc(pr.principle||'')+'" placeholder="The principle, in a single sentence" style="width:100%;padding:8px;border:1px solid rgba(var(--fg-rgb),.12);border-radius:6px;font-size:14px;font-family:inherit;margin-bottom:8px"/>'+ta('Additional details (optional)','pr_e_'+pr.id+'_details',pr.details,'',2)+ta('What, concretely, would breach the principle?','pr_e_'+pr.id+'_breach',pr.breach,'e.g., A customer segment shows systematically worse outcomes traceable to the model.',2)+'<div style="display:flex;gap:8px;flex-wrap:wrap">'+btnS('Save Principle','savePrinciple(\''+pr.id+'\')','#7B4F8A','font-size:12px;padding:5px 12px')+btnG('Cancel','UI.prEdit[\''+pr.id+'\']=false;render()','font-size:12px;padding:5px 12px')+btnG('Remove','removePrincipleById(\''+pr.id+'\')','font-size:12px;padding:5px 12px;color:#9B2D3F')+'</div>','border-left:4px solid #7B4F8A;margin-bottom:8px')}
return card('<div class="xh" onclick="UI.expanded[\''+k+'\']='+(!open)+';render()" style="display:flex;align-items:center;gap:10px;cursor:pointer"><span style="color:var(--text-faint);font-size:15px">'+(open?'\u25be':'\u25b8')+'</span><div style="flex:1;font-size:14px;font-weight:600">'+esc(pr.principle||'')+'</div></div>'+(open?'<div style="margin-top:4px" onclick="event.stopPropagation()">'+f('Details',pr.details)+f('What would breach the principle',pr.breach)+'<div style="margin-top:10px">'+btnG('Edit','UI.prEdit=UI.prEdit||{};UI.prEdit[\''+pr.id+'\']=true;render()','font-size:12px;padding:4px 10px')+'</div></div>':''),'border-left:4px solid #7B4F8A;margin-bottom:8px'+(open?'':';cursor:pointer'))};
var _DOMHINT={'Fairness':'Worth settling here: how will you test for and address bias?','Human Oversight':'Worth settling here: what is your default position on AI autonomy \u2014 who approves, monitors, or intervenes?','Workforce Impact':'Worth settling here: what commitments do you make to employees affected by AI?'};
var addForm=function(dom){return '<div style="padding:12px;border:1px solid rgba(123,79,138,.3);border-radius:8px;margin-bottom:10px">'+(_DOMHINT[dom]?'<p style="font-size:12px;color:var(--text-faint);margin:0 0 8px">'+_DOMHINT[dom]+'</p>':'')+'<input id="pr_new_sentence" placeholder="Set out the principle in a single sentence" style="width:100%;padding:8px;border:1px solid rgba(var(--fg-rgb),.12);border-radius:6px;font-size:14px;font-family:inherit;margin-bottom:8px"/>'+ta('Additional details (optional)','pr_new_details','','',2)+ta('What, concretely, would breach the principle?','pr_new_breach','','e.g., A customer segment shows systematically worse outcomes traceable to the model.',2)+'<div style="display:flex;gap:8px">'+btnS('Save Principle','addPrinciple2()','#7B4F8A','font-size:12px;padding:5px 12px')+btnG('Cancel','UI.prAdd=null;render()','font-size:12px;padding:5px 12px')+'</div></div>'};
doms.forEach(function(dom,di){var list=prs.filter(function(p){return String(p.domain||'')===dom});
h+='<div style="display:flex;align-items:center;gap:10px;margin:16px 0 8px"><div style="font-size:16px;font-weight:700">'+esc(dom)+' <span style="font-weight:400;color:var(--text-faint);font-size:12px">('+list.length+')</span></div><span style="flex:1"></span>'+(UI.prAdd===dom?'':btnAdd('+ Add Principle','prAddOpen('+di+')',null,'font-size:11px;padding:3px 10px'))+'</div>';
h+=list.map(barFor).join('');
if(UI.prAdd===dom)h+=addForm(dom)});
if(UI.domAdd)h+='<div style="display:flex;gap:6px;margin-top:12px"><input id="dom_new" placeholder="Domain name" style="flex:1;padding:8px 12px;border:1px solid rgba(var(--fg-rgb),.15);background:var(--bg-elev);color:var(--paper)"/>'+btnS('Add','addCustomDomain()','#8B4513','font-size:12px;padding:5px 12px')+btnG('Cancel','UI.domAdd=false;render()','font-size:12px;padding:5px 12px')+'</div>';
else h+='<div style="margin-top:12px">'+btnAdd('+ Add Custom Domain','UI.domAdd=true;render()',null,'font-size:12px;padding:5px 12px')+'</div>';
return card(h);
}
var ETH_DOMS=['Fairness','Human Oversight','Workforce Impact','Societal Effects','Transparency'];
function ethDomains(){var ef=data.ethicalFramework||{};var d=ETH_DOMS.slice();(ef.customDomains||[]).forEach(function(x){if(d.indexOf(x)<0)d.push(x)});(ef.principles||[]).forEach(function(p){var pd=String(p.domain||'').trim();if(pd&&d.indexOf(pd)<0)d.push(pd)});return d}
function prAddOpen(i){UI.prAdd=ethDomains()[i];UI.domAdd=false;render()}
function addCustomDomain(){if(lockBlocked('ethicalFramework'))return;var v=(val('dom_new')||'').trim();if(!v)return;var ef=data.ethicalFramework||(data.ethicalFramework={});if(!ef.customDomains)ef.customDomains=[];if(ef.customDomains.indexOf(v)<0&&ETH_DOMS.indexOf(v)<0)ef.customDomains.push(v);UI.domAdd=false;saveData();render()}
function addPrinciple2(){if(lockBlocked('ethicalFramework'))return;var dom=UI.prAdd||'';var s=(val('pr_new_sentence')||'').trim();if(!s){alert('Set out the principle in a single sentence first.');return}
var ef=data.ethicalFramework||(data.ethicalFramework={});if(!ef.principles)ef.principles=[];
ef.principles.push({id:uid(),principle:s,details:(val('pr_new_details')||'').trim(),breach:(val('pr_new_breach')||'').trim(),domain:dom});
UI.prAdd=null;UI.ethRetest=Date.now();saveData();render()}
function savePrinciple(id){if(lockBlocked('ethicalFramework'))return;var ef=data.ethicalFramework||{};var pr=(ef.principles||[]).filter(function(x){return x.id===id})[0];if(!pr)return;var s=(val('pr_e_'+id+'_sentence')||'').trim();if(!s){alert('The principle needs its sentence.');return}
pr.principle=s;pr.details=(val('pr_e_'+id+'_details')||'').trim();pr.breach=(val('pr_e_'+id+'_breach')||'').trim();if(!UI.prEdit)UI.prEdit={};UI.prEdit[id]=false;UI.ethRetest=Date.now();saveData();render()}/* an amendment is a register change \u2014 it prompts the working group */
function removePrincipleById(id){if(lockBlocked('ethicalFramework'))return;var prs2=(data.ethicalFramework||{}).principles||[];for(var i=0;i<prs2.length;i++){if(prs2[i].id===id){if(!confirm('Retire this principle? The board is prompted to commission a review of the change.'))return;removePrinciple(i);return}}}
function render21(){
var ef=data.ethicalFramework||{};var co=data.completedSteps||{};var prs=ef.principles||[];var bd=ef.board||{};var mems=bd.members||[];
var h=vp('V-2.1','Responsible AI Framework','3\u20135 min');
h+='<h2 class="h-section">Step 2.1: Responsible AI Framework</h2><p class="t-lead">This step builds two things. First you establish the Responsible AI Review Board, the named body that maintains the register and keeps it alive. Then you author the register of Responsible AI principles: commitments specific enough that breaching them means something, each carrying a line that says what a breach would look like. The register enables the definition at the heart of the Responsible AI work: a Responsible AI risk is a risk that threatens a breach of one or more named principles. Vague unease becomes a specific claim that can be confirmed or cleared. The register stays open indefinitely. Anyone can propose a principle at any time, and a change to the register prompts the board to commission a review of existing risks against it.</p>';
/* round 37 (10 Aug 2026, Paul's ruling): the board leads; the register follows. */
h+=card('<h3 style="font-size:16px;font-weight:700;margin:0 0 8px;color:var(--t-brown)">Responsible AI Review Board</h3><p style="font-size:13px;color:var(--text-faint);margin-bottom:12px">The board governs the framework, not the risks: it maintains, updates, and sustains the register of Responsible AI principles; runs the periodic review that checks the register is still consistent and sufficient; and reads the screening decisions, the live confirmed risks, and any Responsible AI escalations at its reviews. Risk decisions stay in the portfolios. External experts are explicitly invited. An outside voice keeps the register honest.</p>'
+card('<h3 style="font-size:15px;font-weight:700;margin:0 0 10px">Meeting & Review Cadence</h3>'+sel('Cadence','bd_cadence',bd.cadence,[{v:'',l:'Select...'},{v:'biweekly',l:'Every two weeks'},{v:'monthly',l:'Monthly'},{v:'quarterly',l:'Quarterly'},{v:'custom',l:'Custom rhythm'}])+inp('Cadence detail (optional)','bd_cadenceDetail',bd.cadenceDetail,'e.g., checked at the monthly review; a standalone deep review each quarter'))/* round 43: three subcards, mirroring the dashboard shape */
+card('<h3 style="font-size:15px;font-weight:700;margin:0 0 10px;text-align:center">Board Members</h3>'
+govBoardGlance(mems)/* addendum 214: composition at a glance above the editable rows */
+mems.map(function(m,i){return '<div style="display:flex;gap:8px;margin-bottom:8px;align-items:center"><input id="bm_'+i+'_name" value="'+esc(m.name||'')+'" placeholder="Name" style="flex:1;padding:8px;border:1px solid rgba(var(--fg-rgb),.12);border-radius:6px;font-size:13px;font-family:inherit"/><input id="bm_'+i+'_role" value="'+esc(m.role||'')+'" placeholder="Role" style="flex:2;padding:8px;border:1px solid rgba(var(--fg-rgb),.12);border-radius:6px;font-size:13px;font-family:inherit"/><select id="bm_'+i+'_ext" style="padding:6px 8px;border:1px solid rgba(var(--fg-rgb),.12);border-radius:6px;font-size:13px;font-family:inherit;background:var(--bg-elev);color:var(--paper)"><option value="internal"'+(m.external?'':' selected')+'>Internal</option><option value="external"'+(m.external?' selected':'')+'>External</option></select><button onclick="removeBoardMember('+i+')" style="background:none;border:none;cursor:pointer;color:var(--text-faint)">\u00d7</button></div>'}).join('')
+'<div style="margin:4px 0 16px">'+btnAdd('+ Add Member','addBoardMember()',null,'font-size:13px;padding:6px 14px')+'</div>')
+card('<h3 style="font-size:15px;font-weight:700;margin:0 0 8px">Extraordinary Meeting Criteria</h3><p style="font-size:12px;color:var(--text-faint);margin:0 0 10px">What brings the board together outside its regular cadence?</p>'+escCriteriaRows(bd)));
h+=principleRegisterBody();
/* round 39 (10 Aug 2026, Paul's ruling): the Supplementary Positions card retired \u2014 its three questions live on as add-form prompts in their domains. */
h+=vizEthicsWheel();
h+=doneBtn('saveEF();completeStepGated(\'2.1\')',false,null,'2.1');
return h}
function saveEF(){if(!data.ethicalFramework)data.ethicalFramework={};var ef=data.ethicalFramework;harvestEF();/* round 39: the supplementary-position writes retired with their card (the round-29 wipe guard retires with them) */if(!ef.board)ef.board={};ef.board.cadence=val('bd_cadence');ef.board.cadenceDetail=val('bd_cadenceDetail');saveData();render()}
/* Principle register + board CRUD (D-11(2)(3); ER orgValues shape congruence) */
function harvestEF(){var ef=data.ethicalFramework||{};/* round 37: the pr_i_ always-edit rows retired with the register redesign; principles save through addPrinciple2/savePrinciple */var mems=(ef.board||{}).members||[];for(var j=0;j<mems.length;j++){if(!document.getElementById('bm_'+j+'_name'))break;mems[j].name=val('bm_'+j+'_name');mems[j].role=val('bm_'+j+'_role');mems[j].external=val('bm_'+j+'_ext')==='external'}
if(document.getElementById('esc_0')){var _eb=ef.board||(ef.board={});var _eL=[];for(var k=0;;k++){var _ee=document.getElementById('esc_'+k);if(!_ee)break;if(_ee.value.trim())_eL.push(_ee.value.trim())}_eb.escalationList=_eL}}
/* round 37: addPrinciple retired \u2014 orphaned by the per-domain add flow (addPrinciple2). */
function removePrinciple(i){harvestEF();(data.ethicalFramework.principles||[]).splice(i,1);UI.ethRetest=Date.now();saveData();render()}/* round 34: retirement prompts the working group, same as addition */
/* round 43: the criteria rows as a shared renderer \u2014 the Escalation Criteria subcard on 2.1 and the dashboard alike */
function escCriteriaRows(bd){var escL=bd.escalationList||(bd.escalation?[bd.escalation]:[]);return escL.map(function(x,i){return '<div style="display:flex;gap:8px;margin-bottom:8px;align-items:flex-start"><textarea id="esc_'+i+'" rows="'+Math.max(1,Math.ceil(String(x||'').length/90))+'" placeholder="e.g., a potential breach of any register principle" oninput="this.style.height=\'auto\';this.style.height=this.scrollHeight+\'px\'" style="flex:1;padding:8px 12px;border:1px solid rgba(var(--fg-rgb),.15);background:var(--bg-elev);color:var(--paper);font-family:inherit;font-size:13px;resize:none;overflow:hidden">'+esc(x||'')+'</textarea><span onclick="removeEscCriterion('+i+')" style="cursor:pointer;color:var(--text-faint);font-size:16px;margin-top:8px">\u00d7</span></div>'}).join('')+'<div style="margin:4px 0 4px">'+btnAdd('+ Add Criterion','addEscCriterion()',null,'font-size:13px;padding:6px 14px')+'</div>'}
function addEscCriterion(){if(lockBlocked('ethicalFramework'))return;if(!data.ethicalFramework)data.ethicalFramework={};if(!data.ethicalFramework.board)data.ethicalFramework.board={};harvestEF();var b=data.ethicalFramework.board;if(!b.escalationList)b.escalationList=(b.escalation?[b.escalation]:[]);b.escalationList.push('');saveData();render()}
function removeEscCriterion(i){if(lockBlocked('ethicalFramework'))return;harvestEF();var b=(data.ethicalFramework||{}).board||{};if(!b.escalationList)b.escalationList=(b.escalation?[b.escalation]:[]);b.escalationList.splice(i,1);saveData();render()}
function addBoardMember(){if(lockBlocked('ethicalFramework'))return;if(!data.ethicalFramework)data.ethicalFramework={};if(!data.ethicalFramework.board)data.ethicalFramework.board={};if(!data.ethicalFramework.board.members)data.ethicalFramework.board.members=[];harvestEF();data.ethicalFramework.board.members.push({id:uid(),name:'',role:'',external:false});saveData();render()}
