if(document.getElementById('grl_attendees_0_name')){var A2=[];for(var i=0;;i++){var n=document.getElementById('grl_attendees_'+i+'_name');if(!n)break;var r=document.getElementById('grl_attendees_'+i+'_resp');var nm=n.value.trim(),rp=(r?r.value.trim():'');if(nm||rp)A2.push({name:nm,responsibility:rp})}gr2.attendeesList=A2}
