function govReviewsPlannedBody(){
var rc=data.reviewCadence||{};var gr=data.govRhythm||{};var bd=((data.ethicalFramework||{}).board||{});
var log=(data.reviewLog||[]);
var _cyc=function(f){return f==='weekly'?7:f==='biweekly'?14:f==='monthly'?30:f==='quarterly'?90:f==='biannual'?182:null};
var _last=function(kind){var t=null;log.forEach(function(e){if(e.kind===kind&&(!t||e.at>t))t=e.at});return t};
var _line=function(label,kind,freq){var c=_cyc(freq);var l=_last(kind);var days=l?Math.round((Date.now()-l)/86400000):null;
var status=l?(c?(days<=c*1.5?'On schedule':'Overdue'):'Running'):'Not yet recorded';
var col=status==='Overdue'?'#9B2D3F':(status==='Not yet recorded'?'#C8860A':'#1B6B5A');
return '<div style="display:flex;align-items:center;gap:10px;padding:6px 0;border-top:1px solid rgba(var(--fg-rgb),.05);font-size:13px"><strong style="min-width:160px">'+label+'</strong><span style="color:var(--text-muted)">'+(l?('Last run '+days+' day'+(days!==1?'s':'')+' ago'):'No run recorded')+'</span><span style="margin-left:auto;font-weight:700;color:'+col+'">'+status+'</span></div>'};
return _line('New Risk Review','risk',rc.reviewFrequency)+_line('Responsible AI Board Review','ethics',bd.cadence)+_line('Governance Review','governance',gr.govFrequency)+'<div style="margin-top:8px">'+btnOpen('Open the governance dashboard','go(\'phase5\')')+'</div>'}
