if(_all25.length)h+=card('<div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap"><strong style="font-size:15px">'+_all25.length+' risk'+(_all25.length===1?'':'s')+' awaiting a decision</strong><span style="font-size:13px;color:var(--text-muted)">'+_sc25+' scored</span><span style="font-size:13px;color:var(--text-muted)">'+_rv25+' score'+(_rv25===1?'':'s')+' reviewed</span><span style="flex:1"></span><span style="font-size:13px;font-weight:600;color:'+(_rdone?'#1E6E6E':'var(--text-faint)')+'">'+(_rdone?'All scores reviewed \u2014 Advance and Defer are unlocked.':'Advance and Defer unlock when every score has been reviewed.')+'</span></div>','border-left:4px solid '+(_rdone?'#1E6E6E':'#C8860A')+';margin-bottom:14px');
