// ── TEVV EVIDENCE TRACKER (MEASURE 2.x) — label corrected 22 Aug 2026: no step 3.4 exists in the registry; this machinery serves ttDesignFields and the Compliance Dashboard (5.2) ──
var TEVV_CHARS=[
{k:'valid',n:'Valid & Reliable',sc:'MEASURE 2.5',hint:'Accuracy / performance test results, generalizability limits'},
{k:'safe',n:'Safe',sc:'MEASURE 2.6',hint:'Safety evaluation, fail-safe behavior, response times'},
{k:'secure',n:'Secure & Resilient',sc:'MEASURE 2.7',hint:'Security assessment, adversarial testing, resilience'},
{k:'transparent',n:'Accountable & Transparent',sc:'MEASURE 2.8',hint:'Documentation, disclosure, audit trail'},
{k:'explainable',n:'Explainable & Interpretable',sc:'MEASURE 2.9',hint:'Model explanation, output interpretation in context'},
{k:'privacy',n:'Privacy-Enhanced',sc:'MEASURE 2.10',hint:'Privacy risk assessment, PETs, data minimization'},
{k:'fair',n:'Fair \u2014 Bias Managed',sc:'MEASURE 2.11',hint:'Bias / fairness evaluation results across groups'},
{k:'env',n:'Environmental Impact',sc:'MEASURE 2.12',hint:'Compute / energy footprint of training & operation'}/* chunk 35: promoted from the org-level specialty row to the eighth per-system characteristic (R-5) */
];
var TEVV_STATUS=[{v:'',l:'Not started'},{v:'requested',l:'Evidence requested'},{v:'received',l:'Evidence received'},{v:'verified',l:'Verified'},{v:'na',l:'Not applicable'}];
function tevvColor(st){return st==='verified'?'#1B6B5A':st==='received'?'#C8860A':st==='requested'?'#6B7F8D':st==='na'?'#555':'#9B2D3F'}

/* R-9 (Paul, 21 July): the NIST Template is a second WAY to do testing-and-evidence planning \u2014
   the NIST-structured path many public-sector organizations want. It writes to the SAME stores as
   the free-form tab (s.testingPlan.tests with the char link; s.testEvidence), never a side store. */
function charCoverage(cK){var live=(data.systems||[]).filter(function(s){return !sysExitState(s)});
var done=live.filter(function(s){var t=(((s.testingPlan||{}).tests)||[]).find(function(x){return x.char===cK});return !!t&&(s.testEvidence||[]).some(function(e){return e.testId===t.id})}).length;
return {done:done,total:live.length}}
/* round 85: tplAddNistTest retired with the reference rebuild (Paul, 13 Aug 2026) \u2014 tests enter through the workflow */
/* round 85: tplLogEvidence retired with the reference rebuild (Paul, 13 Aug 2026) \u2014 logging's one home is Tests & Evidence */
var TEVV_DETAIL={valid:'The claim is that the system performs as documented on the data it will actually meet. Evidence that satisfies it: accuracy or performance results against a defined test set, the set\u2019s provenance, and the stated limits of generalization \u2014 where the numbers stop applying.',safe:'The claim is that failure does not injure \u2014 the system degrades safely under bad input, overload, or misuse. Evidence: the safety evaluation, demonstrated fail-safe behavior, and measured response times for containment.',secure:'The claim is that the system resists attack and recovers from disruption. Evidence: the security assessment, adversarial or red-team results, and the recovery test \u2014 what happened when it was knocked over on purpose.',transparent:'The claim is that decisions can be traced and answered for. Evidence: documentation current at the tested version, the disclosure shipped to affected people, and an audit trail a reviewer can actually follow.',explainable:'The claim is that outputs can be explained in the context they are used. Evidence: the explanation method, and a demonstration that the people relying on the outputs interpret them correctly.',privacy:'The claim is that personal data is minimized and protected through the system\u2019s whole path. Evidence: the privacy risk assessment, the minimization applied, and any privacy-enhancing techniques in place, tested at the current version.',fair:'The claim is that harmful bias is measured and managed, not assumed away. Evidence: fairness evaluation results across the groups that matter here, the metric chosen and why, and the threshold that triggers action.',env:'The claim is that the footprint is known and proportionate. Evidence: the compute and energy cost of training and operation, measured or credibly estimated, against the value the system carries.'};/* restored round 85 from copy item 122 */
var TEVV_EX={valid:'For a pricing model: the claim might be \u201cquotes stay within an agreed tolerance of manual pricing,\u201d tested by a monthly sample re-priced by hand.',safe:'For a maintenance model: \u201ca missed fault cannot reach the shop floor unflagged,\u201d tested by replaying known fault cases and checking every one raises an alert.',secure:'For a customer-facing assistant: \u201ccrafted input cannot push it outside its approved scope,\u201d tested by a scheduled attempt to do exactly that.',transparent:'For any system: \u201cevery automated decision can be traced to a responsible person and a documented process,\u201d tested by sampling decisions and following each back through the audit trail.',explainable:'For an applicant-screening model: \u201cevery rejection can be explained to the person affected,\u201d tested by drawing a sample of rejections and writing the explanation for each.',privacy:'For a records system: \u201cpersonal data appears only where it is needed,\u201d tested by searching outputs for personal fields that should have been stripped.',fair:'For a quoting model: \u201clike customers receive like quotes,\u201d tested by comparing quotes across matched cases that differ only in who the customer is.',env:'For a compute-heavy model: \u201cthe running footprint stays inside the stated budget,\u201d tested by reading the quarterly compute and energy figures against it.'};
function tevvFields(){/* round 85 (Paul's ruling): a pure reference; round 86: one parent card owns it */
var h='<div style="padding:16px;border:2px solid #C8860A;border-radius:10px;margin:0 0 14px;background:rgba(200,134,10,.02)">';
h+='<h3 class="h-sub-lg" style="margin:0 0 6px">NIST Reference</h3>';
h+='<p style="font-size:13px;color:var(--text-muted);line-height:1.6;margin:0 0 16px">The NIST AI Risk Management Framework names seven qualities a trustworthy AI system should be able to demonstrate. This reference adds an eighth, environmental impact. NIST calls this testing work TEVV \u2014 Test, Evaluation, Verification, and Validation \u2014 the acronym you will meet wherever this program reports against the framework. This page is a reference: what each quality means, and what testing it might look like. To put one into practice, add it as a claim on the What Needs Testing tab and design its test on Design the Tests. If you want a test to appear on the Analytics testing matrix, pick its NIST measure when you design it.</p>';
TEVV_CHARS.forEach(function(c){
h+=card('<h3 style="font-size:15px;font-weight:700;margin:0 0 2px">'+esc(c.n)+' <span style="font-size:11px;font-weight:600;color:var(--text-faint)">NIST '+esc(c.sc)+'</span></h3>'+
'<p style="font-size:13px;color:var(--text-muted);line-height:1.6;margin:0 0 8px">'+esc(TEVV_DETAIL[c.k]||'')+'</p>'+
'<p style="font-size:13px;line-height:1.6;margin:0">'+(TEVV_EX[c.k]||'')+'</p>','margin-bottom:10px')});
return h+'</div>'}
function testState(s,t){var ev=((s.testEvidence)||[]).filter(function(e){return e.testId===t.id});
if(!ev.length)return 'notrun';
if(t.shape==='recurring'){var per=MN_PERIOD[ttFreqKey(t.frequency)];if(!per)return 'ok';var last=ev[ev.length-1].at;return (last+per*86400000<Date.now())?'overdue':'ok'}
return 'done'}
function testStateBadge(s,t){var st=testState(s,t);var live=!sysExitState(s);
if(st==='overdue')return badge('OVERDUE','#B03030');
if(st==='notrun')return badge('NOT YET RUN',live?'#B03030':'#6B7F8D');
if(st==='done')return badge('Run \u2713','#1B6B5A');
return badge('On schedule','#1B6B5A')}

