var AN={high:'#9B2D3F',med:'#D4A017',low:'#6B7F8D',teal:'#1E6E6E',gold:'#C8860A',green:'#1B6B5A',ink:'var(--text-faint)',grid:'rgba(var(--fg-rgb),.08)',txt:'var(--text-muted)'};
function sevColor(sv){return sv==='high'?AN.high:sv==='medium'?AN.med:AN.low}
function anCard(title,sub,body){return'<div class="cd" style="padding:20px"><div style="font-family:var(--mono);font-size:12px;letter-spacing:.15em;text-transform:uppercase;color:var(--gold-text);margin-bottom:2px">'+title+'</div><div style="font-size:12px;color:var(--text-faint);margin-bottom:14px">'+sub+'</div>'+body+'</div>'}
function anEmpty(msg,stepId,stepName){return'<div style="padding:24px;text-align:center;color:var(--text-faint);font-size:13px">'+msg+(stepId?' <a href="#" onclick="go(\'step\',\''+stepId+'\');return false" style="color:var(--gold-text)">'+stepName+' \u2192</a>':'')+'</div>'}

// ── 1. Risk heatmap: likelihood × importance 5×5 ──
function anHeatmap(){
var risks=data.risks||[];
var scored=risks.filter(function(r){return isLiveRisk(r)&&r.litL&&r.litI});
if(!scored.length)return anEmpty('No LIT-scored risks yet. Score risks in','3.2','Deepen Assessment');
var cells={};scored.forEach(function(r){var k=r.litL+'_'+r.litI;if(!cells[k])cells[k]=[];cells[k].push(r)});
var CS=62,PX=52,PY=14,W=PX+5*CS+16,H=PY+5*CS+44;
var h='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;max-width:480px;display:block;margin:0 auto">';
for(var li=1;li<=5;li++){for(var im=1;im<=5;im++){
var x=PX+(li-1)*CS, y=PY+(5-im)*CS, prod=li*im;
var zone=prod>=15?AN.high:prod>=8?AN.med:AN.teal;
var arr=cells[li+'_'+im]||[];
h+='<rect x="'+x+'" y="'+y+'" width="'+(CS-3)+'" height="'+(CS-3)+'" rx="6" fill="'+zone+'" fill-opacity="'+(arr.length?0.38:0.10)+'" stroke="'+zone+'" stroke-opacity=".35"/>';
if(arr.length){h+='<text x="'+(x+(CS-3)/2)+'" y="'+(y+(CS-3)/2+7)+'" text-anchor="middle" font-size="19" font-weight="700" fill="#F5F2EC">'+arr.length+'</text>';
h+='<title>'+arr.map(function(r){return r.name}).join('\n')+'</title>'}
}}
for(var i=1;i<=5;i++){
h+='<text x="'+(PX+(i-1)*CS+(CS-3)/2)+'" y="'+(PY+5*CS+18)+'" text-anchor="middle" font-size="12" fill="'+AN.ink+'" font-family="monospace">'+i+'</text>';
h+='<text x="'+(PX-12)+'" y="'+(PY+(5-i)*CS+(CS-3)/2+4)+'" text-anchor="end" font-size="12" fill="'+AN.ink+'" font-family="monospace">'+i+'</text>'}
h+='<text x="'+(PX+2.5*CS)+'" y="'+(PY+5*CS+36)+'" text-anchor="middle" font-size="12" fill="'+AN.txt+'">LIKELIHOOD \u2192</text>';
h+='<text x="14" y="'+(PY+2.5*CS)+'" text-anchor="middle" font-size="12" fill="'+AN.txt+'" transform="rotate(-90 14 '+(PY+2.5*CS)+')">IMPACT \u2192</text>';
h+='</svg>';
h+='<div style="display:flex;gap:14px;justify-content:center;margin-top:8px;font-size:12px;color:'+AN.ink+'"><span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:'+AN.teal+';opacity:.7;margin-right:4px"></span>Monitor (\u22646)</span><span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:'+AN.med+';opacity:.7;margin-right:4px"></span>Elevated (8\u201312)</span><span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:'+AN.high+';opacity:.7;margin-right:4px"></span>Critical (\u226515)</span></div>';
return h}

// ── 2. POSTi profile: stacked severity bars per category ──
function anPosti(){
var risks=(data.risks||[]).filter(function(r){return isLiveRisk(r)});
if(!risks.length)return anEmpty('No risks in the register yet. Add risks in','1.3','Identify Risks');
var W=520,BH=26,GAP=14,LX=118,maxW=W-LX-56;
var rows=POSTI.map(function(p){var rs=risks.filter(function(r){return r.category===p.key});
return{p:p,h:rs.filter(function(r){var b=sevBand(r);return b==='critical'||b==='high'}).length,m:rs.filter(function(r){return sevBand(r)==='medium'}).length,l:rs.filter(function(r){var b=sevBand(r);return b==='low'||!b}).length,t:rs.length}});/* chunk 43 (A-2): stacked by composite band, not the dead severity */
var max=Math.max.apply(null,rows.map(function(r){return r.t}).concat([1]));
var H=rows.length*(BH+GAP)+8;
var h='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;display:block">';
rows.forEach(function(r,i){var y=i*(BH+GAP)+4;
h+='<text x="'+(LX-10)+'" y="'+(y+BH/2+4)+'" text-anchor="end" font-size="12" fill="'+AN.txt+'">'+r.p.name+'</text>';
h+='<rect x="'+LX+'" y="'+y+'" width="'+maxW+'" height="'+BH+'" rx="5" fill="rgba(var(--fg-rgb),.04)"/>';
var x=LX;[['h',AN.high],['m',AN.med],['l',AN.low]].forEach(function(seg){var w=r[seg[0]]/max*maxW;if(w>0){h+='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+BH+'" rx="'+(w<10?3:5)+'" fill="'+seg[1]+'" fill-opacity=".85"><title>'+r.p.name+': '+r[seg[0]]+' '+(seg[0]==='h'?'high':seg[0]==='m'?'medium':'low')+'</title></rect>';x+=w}});
if(r.t)h+='<text x="'+(x+8)+'" y="'+(y+BH/2+4)+'" font-size="13" font-weight="700" fill="#F5F2EC">'+r.t+'</text>'});
h+='</svg>';
h+='<div style="display:flex;gap:14px;justify-content:center;margin-top:6px;font-size:12px;color:'+AN.ink+'"><span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:'+AN.high+';margin-right:4px"></span>High</span><span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:'+AN.med+';margin-right:4px"></span>Medium</span><span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:'+AN.low+';margin-right:4px"></span>Low</span></div>';
return h}

// ── 3. Risk pipeline funnel ──
