var gaps=[];
[['approveDeployment','approve an AI deployment'],['requireReview','require a review'],['haltDeployment','halt a deployment'],['reallocateResources','reallocate resources to governance work']].forEach(function(k){if(!String(dr[k[0]]||'').trim())gaps.push('No named holder recorded for the authority to '+k[1]+'.')});
