likSet=function(path,n){
var parts=path.split('.');
if(parts.length===3){
if(parts[0]==='risks'){var risks=data.risks||[];risks.forEach(function(r){if(r.id===parts[1])r[parts[2]]=n});data.risks=risks;saveData();render();return}
if(!data[parts[0]])data[parts[0]]={};if(!data[parts[0]][parts[1]])data[parts[0]][parts[1]]={};data[parts[0]][parts[1]][parts[2]]=n;saveData();render();return}
if(parts.length===2){if(!data[parts[0]])data[parts[0]]={};data[parts[0]][parts[1]]=n;saveData();render();return}
data[parts[0]]=n;saveData();render()};



