/* Addendum 111 / Rollout item 62: outputs print as the user sees them — fold states and
   chosen filters preserved — with the control apparatus stripped: buttons and .np chrome
   removed; selects and typed fields print as their chosen values in plain text. */
function printSanitize(root){
var c=root.cloneNode(true);
var rs=root.querySelectorAll('select'),cs=c.querySelectorAll('select');
for(var i=0;i<cs.length;i++){var tx='';try{var lv=rs[i];tx=(lv&&lv.selectedIndex>=0)?lv.options[lv.selectedIndex].text:''}catch(e){}var sp=document.createElement('span');sp.style.cssText='font-size:13px;font-weight:700';sp.textContent=tx||'\u2014';if(cs[i].parentNode)cs[i].parentNode.replaceChild(sp,cs[i])}
var ri=root.querySelectorAll('input,textarea'),ci=c.querySelectorAll('input,textarea');
for(var j2=0;j2<ci.length;j2++){var v='';try{v=ri[j2]?(ri[j2].value||''):''}catch(e){}var sp2=document.createElement('span');sp2.textContent=v;if(ci[j2].parentNode)ci[j2].parentNode.replaceChild(sp2,ci[j2])}
var kill=c.querySelectorAll('button, .np, [data-np]');
for(var k2=kill.length-1;k2>=0;k2--){var el=kill[k2];if(el.parentNode)el.parentNode.removeChild(el)}
return c.innerHTML}
