function _pdRow(label,val){val=String(val==null?'':val).trim();if(!val)return'';return '<div style="font-size:12px;line-height:1.6;margin:6px 0 0"><span style="color:#666;font-weight:600">'+label+'.</span> '+esc(val)+'</div>'}
function printRiskBlock(r){
var sy=(data.systems||[]).find(function(x){return x.id===r.systemId});
var sysn=r.source==='external'?'External risk':(sy?('AI system: '+sy.name):'');
var cat=(typeof POSTI!=='undefined'&&(POSTI.find(function(x){return x.key===r.category})||{}).name)||r.category||'';
var defd=(r.selection&&r.selection.decision==='defer')?'Deferred':'';
var comp=compositeOf(r);
var h='<div style="padding:12px 0;border-bottom:1px solid #ddd;page-break-inside:avoid">';
h+='<div style="display:flex;justify-content:space-between;gap:14px"><div style="font-size:14px;font-weight:700;color:#111">'+esc(r.name||'')+'</div><div style="font-size:13px;font-weight:700;white-space:nowrap">'+comp+'/15</div></div>';
var meta=[sysn,cat,r.domain||'',defd].filter(Boolean).join(' \u00b7 ');
if(meta)h+='<div style="font-size:11px;color:#666;margin:2px 0 0">'+esc(meta)+'</div>';
/* addendum 118: detail ALWAYS prints — folds are screen navigation, not report content */
h+=_pdRow('What could happen',r.description);
h+=_pdRow('Risk owner',(r.selection||{}).owner);
h+=_pdRow('Expertise needed',Array.isArray(r.needsExpertise)?r.needsExpertise.join(', '):r.needsExpertise);
h+=_pdRow('Required effort',r.needsEffort);
if(r.ethicalFlag===true)h+=_pdRow('Ethical dimension',r.ethicalDesc||'Flagged as potentially crossing a Responsible AI line');
if(r.likelihood||r.impact||r.timeframe)h+=_pdRow('Rapid risk screen','Likelihood '+(r.likelihood||'\u2014')+' \u00b7 Impact '+(r.impact||'\u2014')+' \u00b7 Timeframe '+(r.timeframe||'\u2014')+' \u2014 '+comp+'/15');
var _a=r.assess||{};
if(_a.context||( _a.rootCauses||[]).length||(_a.controls||[]).length||_a.capGaps||_a.likelihoodBasis||(_a.triggers||[]).length){
h+='<div style="font-family:var(--mono,monospace);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#555;margin:10px 0 0">Assessment</div>';
h+=_pdRow('Context',_a.context);
if((_a.rootCauses||[]).length)h+=_pdRow('Root causes',_a.rootCauses.map(function(x,i){return (i+1)+'. '+(x.text||x)+(x.level?' ('+x.level+')':'')}).join('  '));
if((_a.controls||[]).length)h+=_pdRow('Current controls',_a.controls.map(function(x,i){return (i+1)+'. '+(x.text||x)+(x.eff?' \u2014 '+x.eff:'')}).join('  '));
h+=_pdRow('Capability gaps',_a.capGaps);
if(_a.likelihoodBasis){var _lb=_a.likelihoodBasis;h+=_pdRow('Likelihood basis',typeof _lb==='string'?_lb:Object.keys(_lb).map(function(k){return _lb[k]?k+': '+_lb[k]:''}).filter(Boolean).join('  '))}
if((_a.triggers||[]).length)h+=_pdRow('Early-warning triggers',_a.triggers.map(function(x,i){return (i+1)+'. '+(x.indicator||x.text||x)}).join('  '));
}
var lg=[(r.loggedBy||r.createdBy||''),(r.createdAt||r.at)?fmt(r.createdAt||r.at):''].filter(Boolean).join(', ');
h+=_pdRow('Logged by',lg);
return h+'</div>'}
