function _insightCount(feedId){
  var n=0;
  for(var i=0;i<INSIGHT_FEEDS.length;i++){
    var f=INSIGHT_FEEDS[i];
    if(feedId!=='all'&&f.id!==feedId)continue;
    n+=(f._live&&f._live.length?f._live:f.seed).length;
  }
  return n;
}

function buildInsightCards(filterId,view){
  var allItems=[];
  for(var i=0;i<INSIGHT_FEEDS.length;i++){
    var f=INSIGHT_FEEDS[i];
    if(filterId!=='all'&&f.id!==filterId)continue;
    var items=f._live&&f._live.length?f._live:f.seed;
    for(var j=0;j<items.length;j++)allItems.push({feed:f,item:items[j]});
  }
  // Sort by date desc
  allItems.sort(function(a,b){
    var da=a.item.date?new Date(a.item.date.length===7?a.item.date+'-01':a.item.date):new Date(0);
    var db=b.item.date?new Date(b.item.date.length===7?b.item.date+'-01':b.item.date):new Date(0);
    return db-da;
  });
  if(!allItems.length)return'<div style="padding:64px;text-align:center;color:var(--stone);font-family:var(--serif);font-size:20px;font-style:italic">No items found.</div>';

  var isList=(view==='list');
  var h=isList
    ?'<div style="display:flex;flex-direction:column">'
    :'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:18px;margin-top:4px">';

  for(var k=0;k<allItems.length;k++){
    var f2=allItems[k].feed, it=allItems[k].item;
    var isPodcast=(f2.type==='podcast');
    var d=it.date?new Date(it.date.length===7?it.date+'-01':it.date):null;
    var ds=d&&!isNaN(d.getTime())?d.toLocaleDateString('en-US',{year:'numeric',month:'short'}):'';
    var url=it.url||f2.profileUrl;
    var ex=it.excerpt||'';if(ex.length>210)ex=ex.slice(0,207)+'\u2026';

    if(isList){
      h+='<div class="insight-list-row" onclick="window.open(\''+url+'\',\'_blank\')">';
      h+='<div class="insight-badge" style="background:'+f2.color+'18;color:'+f2.color+';border-color:'+f2.color+'35;font-size:12px;padding:3px 8px;white-space:nowrap;min-width:72px;justify-content:center">'+f2.shortLabel+'</div>';
      h+='<div style="flex:1;min-width:0"><div class="insight-list-title">'+(isPodcast?'<span style="color:'+f2.color+'">▶ </span>':'')+esc(it.title)+'</div>';
      if(ex)h+='<div class="insight-list-excerpt">'+esc(ex)+'</div></div>';
      h+='<div class="insight-list-meta">';
      if(ds)h+='<div style="font-family:var(--mono);font-size:12px;color:var(--stone);white-space:nowrap">'+ds+'</div>';
      if(isPodcast&&it.duration)h+='<div style="font-family:var(--mono);font-size:12px;color:var(--stone);margin-top:3px">\u23f1 '+esc(it.duration)+'</div>';
      h+='</div></div>';
    } else {
      h+='<div class="insight-card'+(isPodcast?' insight-card--podcast':'')+'" onclick="window.open(\''+url+'\',\'_blank\')">';
      if(isPodcast)h+='<div style="height:2px;margin:-22px -20px 14px;background:'+f2.color+';opacity:.5"></div>';
      h+='<div class="insight-card-header">';
      h+='<span class="insight-badge" style="background:'+f2.color+'18;color:'+f2.color+';border-color:'+f2.color+'35">'+(isPodcast?'▶ ':'')+f2.shortLabel+'</span>';
      if(ds)h+='<span style="font-family:var(--mono);font-size:12px;color:var(--stone)">'+ds+'</span>';
      h+='</div>';
      h+='<div class="insight-title'+(isPodcast?' insight-title--podcast':'')+'">'+(insightsState.liveLoaded[f2.id]?'<span style="color:'+f2.color+';font-size:12px;font-family:var(--mono);margin-right:4px;vertical-align:middle">●</span>':'')+esc(it.title)+'</div>';
      if(ex)h+='<div class="insight-excerpt">'+esc(ex)+'</div>';
      h+='<div class="insight-card-foot">';
      if(isPodcast&&it.duration)h+='<span style="font-family:var(--mono);font-size:12px;color:var(--stone)">\u23f1 '+esc(it.duration)+'</span>';
      else h+='<span></span>';
      h+='<span class="insight-cta">'+(isPodcast?'Listen':'Read')+' \u2192</span>';
      h+='</div></div>';
    }
  }
  h+='</div>';
  return h;
}

function filterInsights(feedId){
  insightsState.filter=feedId;
  document.querySelectorAll('.insight-filter').forEach(function(b){b.classList.toggle('active',b.getAttribute('data-feed')===feedId);});
  var g=document.getElementById('insightGrid');
  if(g)g.innerHTML=buildInsightCards(feedId,insightsState.view);
}

function setInsightView(v){
  insightsState.view=v;
  var gb=document.getElementById('insightViewGrid'),lb=document.getElementById('insightViewList');
  if(gb)gb.classList.toggle('active',v==='grid');
  if(lb)lb.classList.toggle('active',v==='list');
  var g=document.getElementById('insightGrid');
  if(g)g.innerHTML=buildInsightCards(insightsState.filter,v);
}


/* \u2500\u2500 Chunk 15: gate liveness (D-6) \u2500\u2500 field saves never mark; the Mark Complete
   button is the only completion path, pushable only when the step's criteria hold.
   Criteria = the page's starred gate-fields (DOM, live) + per-step data criteria below. */
function dataGateOK(sid){
if(sid==='1.1'){var _c1=data.completed||{};return ['1.1a','1.1b','1.1c','1.1d','1.1e'].every(function(k){return !!_c1[k]})}
if(sid==='2.2'){var _c2=data.completed||{};return ['2.2a','2.2b','2.2c','2.2d'].every(function(k){return !!_c2[k]})}
if(sid==='1.2')return (data.systems||[]).length>0;
if(sid==='1.3')return (data.risks||[]).length>0;
if(sid==='1.4')return (data.regimes||[]).length>0;/* item 50: the scoping requirement moved to 2.4 with the review */
if(sid==='2.4'){var _r24=data.regimes||[];if(!_r24.length)return false;if(!_r24.every(function(g){return g&&g.scoping&&g.scoping.judgment}))return false;return _r24.filter(function(g){return g.scoping.judgment==='applies'}).every(function(g){return (g.summary&&String(g.summary).trim())||(g.obligations||[]).length>0})}
if(sid==='2.5'){var set=(data.risks||[]).filter(inIdentifyBucket);if(UI.ceremonyScope&&UI.ceremonyScope.length)set=set.filter(function(r){return UI.ceremonyScope.indexOf(r.id)>=0});return set.filter(function(r){return isHighSev(r)&&!(r.selection&&r.selection.decision)}).length===0}
if(sid==='3.1'){return (data.risks||[]).filter(function(r){return isLiveRisk(r)&&ethStatusOf(r)==='potential'}).length===0}/* round 30: the pass's own outcome line, enforced */
if(sid==='4.1'){var P=getPortfolios();return P.manage.filter(needsLanding).length===0}
if(sid==='4.2'){var _g4=data.govRhythm||{};var _a4=_g4.attendeesList||(_g4.attendees?[_g4.attendees]:[]);var _att=_a4.filter(function(x){if(typeof x==='string')return x.trim();x=x||{};return String(x.name||'').trim()||String(x.responsibility||'').trim()}).length>0;var _eo=data.embedOps||{};var _dep=['deploymentGate','lightGate','projectMgmt','hr','procurement'].every(function(f){return String(_eo[f]||'').trim()});return _att&&String(_g4.firstMeeting||'').trim()!==''&&_dep}/* addendum 124: the gate is data-driven across both tabs \u2014 attendees + first date + the five Deployment and Integration fields *//* round 29: attendee requirement became a data criterion when the field became a list; addendum 122 (14 Aug 2026): attendees are name/responsibility pairs — either box counts */
if(sid==='4.3'){var _sysAll=(data.systems||[]).filter(function(s){return s&&!(s.exitDecision&&s.exitDecision.completedAt)});return _sysAll.length>0&&_sysAll.every(function(s){return s&&(s.exitDraft||s.exitDecision)})}/* addendum 133 (15 Aug 2026, ruled): every system gets an exit plan at this step \u2014 retired systems excused */
if(sid==='4.4'){return (data.reviewLog||[]).some(function(e){return e&&e.kind==='governance'})}/* addendum 124: keys realigned to the five ruled agenda items + the first-review RACI item; the old seven-key list could never be satisfied from the page (discovered defect) */
return true}
function dataGateMsg(sid){
if(sid==='1.1')return 'Mark all five sections complete first.';
if(sid==='2.2')return 'Mark all four tabs complete first.';
if(sid==='1.2')return 'Add at least one AI system to the inventory first \u2014 the register is the deliverable.';
if(sid==='1.3')return 'Record at least one risk before this step completes \u2014 the discovery pass is the deliverable.';
if(sid==='1.4'&&!(data.regimes||[]).length)return 'List at least one potential regime before this step completes \u2014 the register is the deliverable.';
if(sid==='2.4'){var _rg2=data.regimes||[];var _n=_rg2.filter(function(g){return !(g&&g.scoping&&g.scoping.judgment)}).length;if(!_rg2.length)return 'The potential register is empty \u2014 list regimes at Step 1.4 first.';if(_n)return _n+' regime'+(_n===1?'':'s')+' still need'+(_n===1?'s':'')+' a scoping judgment \u2014 a reasoned does-not-apply counts.'}
if(sid==='2.4'){var _ng=(data.regimes||[]).filter(function(g){return g&&g.scoping&&g.scoping.judgment==='applies'&&!((g.summary&&String(g.summary).trim())||(g.obligations||[]).length>0)}).length;if(_ng)return _ng+' regime'+(_ng===1?'':'s')+' scoped as applying still need'+(_ng===1?'s':'')+' a summary or at least one obligation \u2014 a summary alone is enough.'}
if(sid==='2.5'){var set=(data.risks||[]).filter(inIdentifyBucket);if(UI.ceremonyScope&&UI.ceremonyScope.length)set=set.filter(function(r){return UI.ceremonyScope.indexOf(r.id)>=0});var n=set.filter(function(r){return isHighSev(r)&&!(r.selection&&r.selection.decision)}).length;return 'Every risk on the Urgent list needs a decision before selection closes \u2014 '+n+' still missing. Advance each one under a named owner, or defer it with a named trigger and revisit horizon.'}
if(sid==='3.1'){var _n31=(data.risks||[]).filter(function(r){return isLiveRisk(r)&&ethStatusOf(r)==='potential'}).length;return 'Screen every pending flag first \u2014 '+_n31+' still await'+(_n31===1?'s':'')+' it. Each becomes confirmed or cleared.'}
if(sid==='4.1'){var P=getPortfolios();var n=P.manage.filter(needsLanding).length;if(n)return n+(n===1?' card still needs':' cards still need')+' attention \u2014 every Manage-portfolio card needs its plan before this step completes.'}
if(sid==='4.2'){var _g4m=data.govRhythm||{};var _eo4=data.embedOps||{};var _miss=[];var _a4m=(_g4m.attendeesList||[]).filter(function(x){if(typeof x==='string')return x.trim();x=x||{};return String(x.name||'').trim()||String(x.responsibility||'').trim()}).length;if(!_a4m)return 'Add at least one attendee to the standing meeting first.';/* ruled 16 Aug 2026: the attendee gate stands alone per the master */if(!String(_g4m.firstMeeting||'').trim())_miss.push('the first meeting date');if(!['deploymentGate','lightGate','projectMgmt','hr','procurement'].every(function(f){return String(_eo4[f]||'').trim()}))_miss.push('the Deployment and Integration fields');return 'Complete both tabs first \u2014 still needed: '+_miss.join(', ')+'.'}
if(sid==='4.3')return 'Every system needs its standing exit plan before this step completes \u2014 open each system in the list and write the plan on its Exit Plan page.';
if(sid==='4.4'){if(!(data.reviewLog||[]).some(function(e){return e&&e.kind==='governance'}))return 'Hold the review first \u2014 cover every agenda item, answer the three questions, and click Save governance review. The step completes once the review is saved.'}
return 'Complete required fields (*) first.'}
function gateFieldsClear(){var els=document.querySelectorAll('#app .gate-field');for(var i=0;i<els.length;i++){var el=els[i],empty;if(el.classList.contains('gate-likert')){empty=!el.querySelector('.lk-btn.sel')}else{empty=!String(el.value||'').trim()}if(empty)return false}return true}
function confirmStepDone(sid){if((data.completedSteps||{})[sid])return true;return confirm('Mark this step complete? This will notify the team and cannot be undone.')}
function confirmSectionDone(k){if((data.completed||{})[k])return true;return confirm('Mark this section complete? This can\u2019t be undone.')}
function nextStepAfter(sid){var order=[];(PHASES||[]).forEach(function(p){(p.steps||[]).forEach(function(st){order.push(st.id)})});var i=order.indexOf(sid);return (i>=0&&i<order.length-1)?order[i+1]:null}
function completeStepGated(sid){
if(!dataGateOK(sid)){alert(dataGateMsg(sid));return}
if(!gateFieldsClear()){gateArmed=true;paintGates();alert('Complete required fields (*) first.');return}
if(!confirmStepDone(sid))return;
completeStep(sid);
var _ph52=PHASES.find(function(p){return (p.steps||[]).some(function(st){return st.id===sid})});
var _last52=_ph52&&_ph52.steps[_ph52.steps.length-1].id===sid;
var _nx=nextStepAfter(sid);
if(_nx&&!_last52)go('step',_nx)}/* item 52: the last step of a phase stays on the page \u2014 the milestone and phase-complete cards are the reward */
function refreshGates(){try{var fieldsOk=gateFieldsClear();var dataOk=dataGateOK(currentStep);var btns=document.querySelectorAll('#app .done-btn');for(var i=0;i<btns.length;i++){var b=btns[i];if(b.classList.contains('done-btn-complete'))continue;var isStep=String(b.getAttribute('onclick')||'').indexOf('completeStepGated')>=0;b.disabled=isStep?!(fieldsOk&&dataOk):!fieldsOk}}catch(e){}}
function completeStep(id){
if(!data.completedSteps)data.completedSteps={};
data.completedSteps[id]=true;
stampStepDone(id);
saveData();render();
}

/* ═══════════════════════════════════════════════════════════
   TRACK PROGRAM (Module Management hub) — ported from the
   innovation app (July 13): step assignments, deadlines,
   pacing analytics, and the notification queue.
   ═══════════════════════════════════════════════════════════ */
function backBtn(){return '<button class="btn-ghost pad-chip-sm" onclick="go(\'home\')">\u2190 Back</button>'}

function getAssigns(taskId){
  return (data.assigns || {})[taskId] || [];
}

function toggleAssign(taskId, uid){
  if(!data.assigns) data.assigns = {};
  var cur = data.assigns[taskId] || [];
  if(cur.indexOf(uid) >= 0){
    data.assigns[taskId] = cur.filter(function(x){return x !== uid});
  } else {
    data.assigns[taskId] = cur.concat([uid]);
  }
  saveData();
  render();
}

function stepAssignBar(stepId){
  if(!stepId) return '';
  if(/^5\./.test(String(stepId)))return'';/* fix batch 1 item 1 (R-1/F-1, 20 Aug 2026): phase-5 pages carry no assign bar — nothing counts those assignments */
  return '<div class="assign-bar">'
    + '<div class="assign-bar-lbl">Assigned to</div>'
    + assignBtn(stepId)
    + '</div>';
}

function assignBtn(taskId){
  var assigns = getAssigns(taskId);
  var isOpen = UI.assignOpen === taskId;
  var h = '<div class="assign-wrap">';
  // Assigned avatars
  assigns.forEach(function(uid){
    var u = USERS.find(function(x){return x.id===uid});
    if(u) h += '<span class="assign-av" style="cursor:pointer" title="'+esc(u.name)+' \u2013 click to manage assignments" onclick="event.stopPropagation();UI.assignOpen=UI.assignOpen===\''+taskId+'\'?null:\''+taskId+'\';render()">'+userAv(u,24)+'</span>';
  });
  // + Assign button
  h += '<button class="assign-add" style="width:24px;height:24px;padding:0;border-radius:50%;border:1px dashed rgba(var(--fg-rgb),.45);background:none;display:inline-flex;align-items:center;justify-content:center;font-size:14px;line-height:1" title="Assign members" onclick="event.stopPropagation();UI.assignOpen=UI.assignOpen===\''+taskId+'\'?null:\''+taskId+'\';render()">+</button>';
  // Picker popover
  if(isOpen){
    h += '<div class="assign-pop">';
    h += '<div class="t-faint-sm" style="padding:6px 8px 4px">Click a name to assign or unassign \u2013 changes save instantly. Done closes the picker.</div>';
    var _sorted = USERS.slice().sort(function(a,b){var sa=assigns.indexOf(a.id)>=0?0:1,sb=assigns.indexOf(b.id)>=0?0:1;return sa-sb});
    _sorted.forEach(function(u){
      var isSel = assigns.indexOf(u.id) >= 0;
      h += '<button class="assign-row"'+(isSel?'':' style="opacity:.55"')+' title="'+(isSel?'Click to remove':'Click to assign')+'" onclick="event.stopPropagation();toggleAssign(\''+taskId+'\',\''+u.id+'\')">'
        + userAv(u,22)
        + '<div class="assign-row-text"><div class="assign-row-name">'+esc(u.name)+'</div>'
        + '<div class="assign-row-role">'+esc(u.role)+'</div></div>'
        + '<span class="assign-row-check">'+(isSel?'✓':'+')+'</span>'
        + '</button>';
    });
    h += '<button class="assign-close" onclick="event.stopPropagation();UI.assignOpen=null;render()">Done</button>';
    h += '</div>';
  }
  return h + '</div>';
}

function stampStepDone(id){try{if(!data.stepDoneAt)data.stepDoneAt={};if(!data.stepDoneAt[id]){data.stepDoneAt[id]=new Date().toISOString().split('T')[0];if(!data.stepDoneBy)data.stepDoneBy={};var _cu=(typeof getCurrentUser==='function'&&getCurrentUser())||null;data.stepDoneBy[id]=_cu?(_cu.name||''):'';/* ATTRIB@stepDoneBy fix (R2 triage, 25 Aug 2026, ruled family law): step completion records the completing user alongside the date, matching action-level attribution; written only inside the first-stamp guard, so re-saves never rewrite it */Store.commit('stepDoneAt');notifyStepComplete(id)}}catch(e){}}

function mgSteps(){var out=[];PH.forEach(function(p){if(p.id===5)return;p.steps.forEach(function(st){out.push({id:st.id,name:st.name,icon:st.icon,ph:p})})});return out}

function deferRender(){setTimeout(render,0)} /* item 18 family form: date inputs save on change with no confirm step, render deferred to blur */
function mgDueSave(id,v){data.stepDue=data.stepDue||{};if(v)data.stepDue[id]=v;else delete data.stepDue[id];Store.commit('stepDue')}/* item 11 EXCLUSION (21 Aug 2026): date inputs stay silent on change and render on blur — the item-18 ruling; render-on-change with an open date picker is the closed crash class */

function mgAssignToggle(id,uid2){toggleAssign(id,uid2)}

function mgStats(){var steps=mgSteps(),co=data.completedSteps||{},due=data.stepDue||{};
var done=steps.filter(function(s){return co[s.id]}).length;
var sd=data.startDate?new Date(data.startDate):new Date();
var elapsed=Math.max(0,Math.round((Date.now()-sd.getTime())/86400000));
var ideal=Math.min(1,elapsed/90)*steps.length;
var today=new Date().toISOString().split('T')[0];
var overdue=steps.filter(function(s){return !co[s.id]&&due[s.id]&&due[s.id]<today}).length;
return{total:steps.length,done:done,elapsed:elapsed,ideal:ideal,delta:done-ideal,overdue:overdue}}

function mgBurnup(){var steps=mgSteps(),total=steps.length;var co=data.completedSteps||{},dts=data.stepDoneAt||{};
var sd=data.startDate?new Date(data.startDate):new Date();
var events=[];steps.forEach(function(s){if(co[s.id]&&dts[s.id])events.push({d:new Date(dts[s.id]),id:s.id})});
events.sort(function(a,b){return a.d-b.d});
var elapsed=Math.max(0,Math.min(120,Math.round((Date.now()-sd.getTime())/86400000)));
var span=Math.max(90,elapsed);
var W=560,H=190,PX=40,PY=12,PW=W-PX-16,PHt=H-PY-34;
var X=function(day){return PX+day/span*PW},Y=function(nn){return PY+PHt-(nn/total)*PHt};
var h='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;display:block">';
[0,.5,1].forEach(function(f){var y=PY+PHt-f*PHt;h+='<line x1="'+PX+'" y1="'+y.toFixed(1)+'" x2="'+(PX+PW)+'" y2="'+y.toFixed(1)+'" stroke="rgba(245,242,236,.08)"/><text x="'+(PX-6)+'" y="'+(y+4).toFixed(1)+'" text-anchor="end" font-size="9" fill="#8A8278">'+Math.round(f*total)+'</text>'});
[30,60,90].forEach(function(d){if(d<=span)h+='<line x1="'+X(d).toFixed(1)+'" y1="'+PY+'" x2="'+X(d).toFixed(1)+'" y2="'+(PY+PHt)+'" stroke="rgba(245,242,236,.08)" stroke-dasharray="2 4"/><text x="'+X(d).toFixed(1)+'" y="'+(PY+PHt+16)+'" text-anchor="middle" font-size="9" fill="#8A8278">day '+d+'</text>'});
h+='<line x1="'+X(0).toFixed(1)+'" y1="'+Y(0).toFixed(1)+'" x2="'+X(Math.min(90,span)).toFixed(1)+'" y2="'+Y(total).toFixed(1)+'" stroke="#8A8278" stroke-dasharray="4 4" stroke-opacity=".6"><title>Ideal pace: all '+total+' steps by day 90</title></line>';
var pth=['M'+X(0).toFixed(1)+' '+Y(0).toFixed(1)],n=0;
events.forEach(function(e){var day=Math.max(0,Math.min(span,Math.round((e.d-sd)/86400000)));pth.push('L'+X(day).toFixed(1)+' '+Y(n).toFixed(1));n++;pth.push('L'+X(day).toFixed(1)+' '+Y(n).toFixed(1))});
pth.push('L'+X(Math.min(elapsed,span)).toFixed(1)+' '+Y(n).toFixed(1));
h+='<path d="'+pth.join(' ')+'" fill="none" stroke="#D4A017" stroke-width="2"/>';
h+='<circle cx="'+X(Math.min(elapsed,span)).toFixed(1)+'" cy="'+Y(n).toFixed(1)+'" r="4" fill="#D4A017"/>';
h+='<text x="'+X(Math.min(elapsed,span)).toFixed(1)+'" y="'+(Y(n)-8).toFixed(1)+'" text-anchor="middle" font-size="9" fill="#D4A017">TODAY \u00b7 '+n+'/'+total+'</text></svg>';
var st=mgStats();
h+='<div class="t-faint-sm" style="text-align:center;margin-top:4px;color:'+(st.delta>=0?'var(--ok-t)':'var(--t-crit)')+'">'+(st.delta>=0?'\u25b2 ':'\u25bc ')+Math.abs(st.delta).toFixed(1)+' steps '+(st.delta>=0?'ahead of':'behind')+' the ideal pace</div>';
return h}

function mgVelocity(){var dts=data.stepDoneAt||{},co=data.completedSteps||{};
var sd=data.startDate?new Date(data.startDate):new Date();
var weeks=[],i;for(i=0;i<13;i++)weeks.push(0);var any=false;
mgSteps().forEach(function(s){if(co[s.id]&&dts[s.id]){any=true;var w=Math.floor((new Date(dts[s.id])-sd)/(7*86400000));if(w<0)w=0;if(w>12)w=12;weeks[w]++}});
if(!any)return'<p class="t-faint-sm">No completion dates recorded yet \u2013 velocity appears as steps are marked complete.</p>';
var curW=Math.min(12,Math.max(0,Math.floor((Date.now()-sd.getTime())/(7*86400000))));
var W=560,H=170,PX=26,PY=20,PW=W-PX-10,PHt=H-PY-28;
var bw=PW/13,mx=Math.max.apply(null,weeks.concat([1]));
var h='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;display:block">';
weeks.forEach(function(v,j){var bh=v/mx*PHt,x=PX+j*bw+3,y=PY+PHt-bh;var col=j===curW?'#D4A017':'#4FB39A';
h+='<rect x="'+x.toFixed(1)+'" y="'+PY+'" width="'+(bw-6).toFixed(1)+'" height="'+PHt+'" rx="4" fill="rgba(245,242,236,.03)"/>';
if(v)h+='<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+(bw-6).toFixed(1)+'" height="'+bh.toFixed(1)+'" rx="4" fill="'+col+'" fill-opacity=".85"><title>Week '+(j+1)+': '+v+' step'+(v>1?'s':'')+'</title></rect>';
if(v)h+='<text x="'+(x+(bw-6)/2).toFixed(1)+'" y="'+(y-4).toFixed(1)+'" text-anchor="middle" font-size="10" font-weight="700" fill="#F5F2EC">'+v+'</text>';
h+='<text x="'+(x+(bw-6)/2).toFixed(1)+'" y="'+(PY+PHt+16)+'" text-anchor="middle" font-size="8.5" fill="'+(j===curW?'#D4A017':'#8A8278')+'">W'+(j+1)+'</text>'});
h+='</svg><div class="t-faint-sm" style="text-align:center;margin-top:4px">Gold bar = current program week</div>';
return h}

function mgSignals(){var steps=mgSteps(),co=data.completedSteps||{},due=data.stepDue||{},dts=data.stepDoneAt||{},assigns=data.assigns||{};
var _rIds={};(USERS||[]).forEach(function(u){if(u&&u.id)_rIds[u.id]=1});var withOwner=steps.filter(function(s){return(assigns[s.id]||[]).some(function(a){return _rIds[a]})}).length;/* fix batch 1 item 8: Signals counts only owners still on the roster */
var withDue=steps.filter(function(s){return due[s.id]}).length;
var met=0,miss=0;steps.forEach(function(s){if(co[s.id]&&due[s.id]&&dts[s.id]){if(dts[s.id]<=due[s.id])met++;else miss++}});
var sd=data.startDate?new Date(data.startDate):new Date();
var h='<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;text-align:center">';
var cellS=function(v,l){return'<div><div class="fs-14"><strong>'+v+'</strong></div><div class="t-faint-sm" style="margin-top:2px">'+l+'</div></div>'};
h+=cellS(withOwner+' of '+steps.length,'steps with an owner');
h+=cellS(withDue+' of '+steps.length,'steps with a deadline');
h+=cellS((met+miss)?met+' met \u00b7 '+miss+' missed':'\u2014','deadlines on completed steps');
h+='</div>';
var meds=PH.filter(function(p){return p.id!==5}).map(function(p){var ds=p.steps.filter(function(st){return co[st.id]&&dts[st.id]}).map(function(st){return Math.round((new Date(dts[st.id])-sd)/86400000)}).sort(function(a,b){return a-b});var med=ds.length?ds[Math.floor((ds.length-1)/2)]:null;var doneN=p.steps.filter(function(st){return co[st.id]}).length;return{p:p,med:med,doneN:doneN,n:p.steps.length}});
h+='<div style="margin-top:10px">'+meds.map(function(x){return'<div class="row-line"><span class="fs-13" style="flex:1;color:'+x.p.color+'">Phase '+x.p.id+' \u2013 '+esc(x.p.name)+'</span><span class="t-faint-sm">'+x.doneN+' / '+x.n+' complete'+(x.med!=null?' \u00b7 median completion day '+x.med:'')+'</span></div>'}).join('')+'</div>';
return h}

function mgWeek(){var steps=mgSteps(),co=data.completedSteps||{},due=data.stepDue||{};
var today=new Date().toISOString().split('T')[0];
var week=new Date(Date.now()+7*86400000).toISOString().split('T')[0];
var overdue=steps.filter(function(s){return !co[s.id]&&due[s.id]&&due[s.id]<today});
var upcoming=steps.filter(function(s){return !co[s.id]&&due[s.id]&&due[s.id]>=today&&due[s.id]<=week});
if(!overdue.length&&!upcoming.length)return'<p class="t-faint-sm">Nothing due in the next seven days and nothing overdue.</p>';
return overdue.concat(upcoming).map(function(s2){return mgRowHtml(s2.id,s2.name)}).join('')}

function mgRowHtml(id2,name){var co=data.completedSteps||{},due=data.stepDue||{},dts=data.stepDoneAt||{};
var today=new Date().toISOString().split('T')[0];
var doneS=!!co[id2];var d2=due[id2]||'';var over=!doneS&&d2&&d2<today;
return '<div style="display:grid;grid-template-columns:minmax(160px,1fr) 300px 240px;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid rgba(var(--fg-rgb),.06)">'
+'<div style="display:flex;align-items:baseline;gap:10px"><span class="t-faint-sm" style="min-width:26px">'+id2+'</span><span class="fs-14">'+esc(name)+'</span></div>'
+'<div style="display:flex;justify-content:flex-start;align-items:center;gap:8px;flex-wrap:wrap">'
+(doneS?badge('\u2713 done'+(dts[id2]?' \u00b7 '+fmtDate(dts[id2]):''),'#1B6B5A')+(d2?'<span class="t-faint-sm">was due '+fmtDate(d2)+'</span>':''):over?badge('overdue \u00b7 was due '+fmtDate(d2),'#C25B73'):d2?badge('due '+fmtDate(d2),'#D4A017'):badge('open','#2D5A8E'))
+(doneS?'':'<input type="date" value="'+esc(d2)+'" onchange="mgDueSave(\''+id2+'\',this.value)" onblur="deferRender()" title="Optional deadline" style="font-size:11px;padding:3px 6px;background:rgba(var(--fg-rgb),.04);color:var(--paper);border:1px solid rgba(var(--fg-rgb),.15);border-radius:6px"/>')
+'</div>'
+'<div style="display:flex;justify-content:flex-end;flex-wrap:wrap;gap:2px">'+assignBtn(id2)+'</div>'
+'</div>'}

function mgWorkload(){var steps=mgSteps(),co=data.completedSteps||{},assigns=data.assigns||{};
var rows=USERS.map(function(u){var open=0,done=0;steps.forEach(function(s){if((assigns[s.id]||[]).indexOf(u.id)>=0){if(co[s.id])done++;else open++}});return{u:u,open:open,done:done}}).filter(function(r){return r.open+r.done>0});
if(!rows.length)return'<p class="t-faint-sm">No assignments yet \u2013 assign members on the Assignments tab.</p>';
var mx=Math.max.apply(null,rows.map(function(r){return r.open+r.done}));
rows.sort(function(a,b){return(b.open-a.open)||(b.done-a.done)});
var h='';rows.forEach(function(r){
var wO=(r.open/mx)*100,wD=(r.done/mx)*100;
h+='<div style="display:flex;align-items:center;gap:10px;padding:5px 0"><div style="width:26px">'+userAv(r.u,24)+'</div><div class="fs-13" style="width:140px">'+esc(r.u.name)+'</div>'
+'<div style="flex:1;height:12px;background:rgba(var(--fg-rgb),.05);border-radius:6px;overflow:hidden;display:flex">'
+(r.open?'<div style="width:'+wO.toFixed(1)+'%;background:#D4A017"><title></title></div>':'')
+(r.done?'<div style="width:'+wD.toFixed(1)+'%;background:#4FB39A;opacity:.45"></div>':'')
+'</div><div class="t-faint-sm" style="width:130px;text-align:right">'+r.open+' open \u00b7 '+r.done+' complete</div></div>'});
h+='<div class="t-faint-sm" style="margin-top:6px">Sorted by open load \u2013 gold is open work, faded teal is complete.</div>';
return h}

function mgmtHubContent(){ /* the hub body, callable for the page, the PDF, and the notification emails (July 7) */
var st=mgStats(),co=data.completedSteps||{},due=data.stepDue||{},dts=data.stepDoneAt||{},assigns=data.assigns||{};
var today=new Date().toISOString().split('T')[0];
var h='<div class="mb-6">'+badge('Ongoing','#6B4C8A')+'<h1 class="section-title u-967e19d">Module <em>Management</em></h1><p class="u-98b80d8">Every step of the module in one place \u2013 who owns it, when it is due, and how completion is pacing against the 90 days.</p></div>';
var tile=function(v,l,c){return'<div style="text-align:center"><div class="score-num-md" style="font-size:26px;line-height:1.2'+(c?';color:'+c:'')+'">'+v+'</div><div class="t-faint-sm" style="margin-top:3px">'+l+'</div></div>'};
h+=card('<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:14px">'
+tile(st.done+' / '+st.total,'steps complete')
+tile('Day '+Math.min(st.elapsed,90)+(st.elapsed>90?' (+'+(st.elapsed-90)+' over)':''),'of the 90')
+tile((st.delta>=0?'+':'\u2212')+Math.abs(st.delta).toFixed(1),'steps vs ideal pace',st.delta>=0?'var(--ok-t)':'var(--t-crit)')
+tile(String(st.overdue),'overdue',st.overdue?'var(--t-crit)':null)
+'</div>','margin-bottom:16px');
var _mt=UI.mgTab||0;
var _mtb=function(n,l){return'<button class="btn-ghost pad-chip-md'+(_mt===n?' nav-action-on':'')+'" style="font-size:13px'+(_mt===n?';border-color:#D4A017;color:#D4A017':'')+'" onclick="UI.mgTab='+n+';render()">'+l+'</button>'};
h+='<div style="display:flex;gap:8px;margin-bottom:16px">'+_mtb(0,'Assignments')+_mtb(1,'Analytics')+'</div>';
if(_mt===1){
h+=card('<h3 class="h-sub-md">90-Day Burn-up</h3><p class="t-faint-sm" style="margin:4px 0 10px">Cumulative step completion against the ideal pace \u2013 the dashed line finishes all '+st.total+' steps by day 90.</p>'+mgBurnup(),'margin-bottom:16px');
h+=card('<h3 class="h-sub-md">Module Velocity</h3><p class="t-faint-sm" style="margin:4px 0 10px">Steps completed per program week, from completion dates.</p>'+mgVelocity(),'margin-bottom:16px');
h+=card('<h3 class="h-sub-md">Workload by Member</h3><p class="t-faint-sm" style="margin:4px 0 10px">Open and completed step assignments \u2013 gold shows who is carrying open work now.</p>'+mgWorkload(),'margin-bottom:16px');
h+=card('<h3 class="h-sub-md">Signals</h3>'+mgSignals(),'margin-bottom:16px');
}else{
h+=card('<h3 class="h-sub-md">This Week</h3><p class="t-faint-sm" style="margin:4px 0 8px">Steps overdue or due within seven days.</p>'+mgWeek(),'margin-bottom:16px');
PH.forEach(function(p){if(p.id===5)return;
var rows='';p.steps.forEach(function(stp){var id2=stp.id;
rows+=mgRowHtml(id2,stp.name)});
h+=card('<h3 class="h-sub-md" style="color:'+p.color+'">Phase '+p.id+' \u2013 '+esc(p.name)+' <span class="t-faint-sm" style="font-weight:400">('+p.days+')</span></h3>'+rows,'margin-bottom:16px');
});
}
return h}

function notifyMemberEmails(list){return (list||USERS||[]).map(function(u){return u&&u.email}).filter(function(e){return e&&/\S+@\S+/.test(e)})}

function notifyAdmins(){return (USERS||[]).filter(function(u){return u&&(u.admin===true||/admin/i.test(u.role||''))})}/* fix batch 1 item 3 (R-2, Spec §12, 20 Aug 2026): role-contains-admin joins; the creator flag stays so the org creator never silently drops off reminders — disclosed superset */

function notifyStepName(id){var nm=id;(PH||[]).forEach(function(p){(p.steps||[]).forEach(function(st){if(st.id===id)nm='Step '+st.id+' \u2013 '+st.name})});return nm}

function notifyQueue(kind,subject,to,stepId,pdf){
if(SAMPLE_MODE)return; /* Part 3: the sample tab sends no email */
if(!to||!to.length)return;
if(!data.notifications)data.notifications=[];
var n={at:Date.now(),kind:kind,subject:subject,to:to,stepId:stepId||'',pdf:!!pdf,status:NOTIFY_ENDPOINT?'sending':'pending \u2013 endpoint not configured'};
data.notifications.push(n);if(data.notifications.length>50)data.notifications=data.notifications.slice(-50);
Store.commit('notifications');
notifyDispatch(n);return n}

function notifyEmailHtml(n){
var head='<h2 style="font-family:Helvetica,Arial,sans-serif">'+esc(n.subject)+'</h2><p>'+(n.kind==='step-complete'?esc(notifyStepName(n.stepId))+' was marked complete on '+fmtDate(n.at)+'. The current Module Management analytics report is attached.':'The assigned step '+esc(notifyStepName(n.stepId))+' is due within one week ('+esc(((data.stepDue||{})[n.stepId]?fmtDate((data.stepDue||{})[n.stepId]):''))+').')+'</p>';
return n.kind==='step-complete'?head+'<hr/>'+(function(){var _t=UI.mgTab;UI.mgTab=1;var hub=mgmtHubContent();UI.mgTab=_t;return hub;})():head} /* the completion email always embeds the Analytics page */

function notifyDispatch(n){
if(!NOTIFY_ENDPOINT)return; /* inert until wired \u2013 outbox holds the record */
try{fetch(NOTIFY_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:n.kind,subject:n.subject,to:n.to,stepId:n.stepId,orgName:(data.enterprise||{}).name||'',sentAt:new Date(n.at).toISOString(),pdf:n.pdf,html:notifyEmailHtml(n)})})
.then(function(r){n.status=r.ok?'sent':'failed ('+r.status+')';Store.commit('notifications');render()})
.catch(function(){n.status='failed (network)';Store.commit('notifications');render()})}catch(e){n.status='failed';Store.commit('notifications')}}

function notifyStepComplete(id){
try{var to=notifyMemberEmails();if(!to.length)return;
notifyQueue('step-complete',notifyStepName(id)+' complete \u2013 analytics report',to,id,true)}catch(e){}}

function notifySweepDeadlines(){
try{var due=data.stepDue||{},assigns=data.assigns||{},co=data.completedSteps||{};
if(!data.remind7)data.remind7={};
var today=new Date();today.setHours(0,0,0,0);
Object.keys(due).forEach(function(id){
if(!due[id]||co[id]||data.remind7[id])return;
var who=assigns[id]||[];if(!who.length)return; /* reminders are for ASSIGNED deadlines */
var d=new Date(due[id]+'T00:00:00');var days=Math.round((d-today)/86400000);
if(days<0||days>7)return;
var admins=notifyAdmins();
var to=notifyMemberEmails(admins.concat((USERS||[]).filter(function(u){return who.indexOf(u.id)>=0&&admins.indexOf(u)<0})));
if(!to.length)return;
var n=notifyQueue('deadline-reminder',notifyStepName(id)+' due '+due[id],to,id,false);
if(n&&!admins.length)n.status+=' \u00b7 no administrator on the roster';
data.remind7[id]=true;Store.commit('remind7')})}catch(e){}}

function notifyOutboxCard(){ /* not mounted – kept demo-clean (Paul, July 7); remount in renderMgmtHub if an in-app delivery log is wanted once AWS is wired */
var ns=(data.notifications||[]).slice(-8).reverse();
var rows=ns.map(function(n){return'<div class="row-line"><span class="fs-13" style="flex:1">'+esc(n.subject)+'</span><span class="t-faint-sm">'+fmtDate(n.at)+' \u00b7 '+n.to.length+' recipient'+(n.to.length>1?'s':'')+' \u00b7 '+esc(n.status)+'</span></div>'}).join('');
return card('<h3 class="h-sub-md">Email Notifications</h3><p class="t-faint-sm" style="margin:-2px 0 8px">Step-completion reports go to the whole team. Deadline reminders go to the administrator and the assignees one week out. '+(NOTIFY_ENDPOINT?'Dispatching to the configured service.':'The dispatch service is not yet wired \u2013 notifications queue here until the dev team connects AWS.')+'</p>'+(rows||'<p class="t-faint-sm">\u2014</p>'),'margin-bottom:16px')}

function renderMgmtHub(){var _w='<div class="content-area pt-110"><div class="content-inner">';
return _w+backBtn()+'<div style="display:flex;justify-content:flex-end;margin:0 0 10px">'+'<button class="btn bg2" style="font-size:12px" onclick="printMgmtAnalytics()">\u25be Save as PDF</button>'+'</div>'+mgmtHubContent()+'</div></div>'}

function printMgmtAnalytics(){printPage('Module Management',mgmtHubDoc())} /* 14 Sep 2026 (Paul's ruling): the Track Program page prints as its own document */

// === COACH ===
/* -- AI FEATURES (Directive 2 Oct 2026, Part 2): the AI Guide and Voice are off until an administrator of the organization switches them on. Data without settings counts as both off. -- */
function aiGuideOn(){ return !SAMPLE_MODE && !!(data && data.settings && data.settings.aiGuide); }
function voiceOn(){ return !SAMPLE_MODE && !!(data && data.settings && data.settings.voice); }
function canSetAiFeatures(){ var u=getCurrentUser(); return !!isAppAdmin || !!(u && u.admin===true); } /* admin:true is the authority record (ruled July 9) */
/* Run on every render and after a change: the buttons shown or hidden, an open AI Guide closed and a live microphone stopped when switched off. */
function applyAiFeatures(){
  var ai=aiGuideOn(), vo=voiceOn();
  if(!ai && coachOpen){ try{ toggleCoach(); }catch(e){} }
  if(!vo && _voiceActive){ _voiceActive=false; try{ if(_recognition) _recognition.stop(); }catch(e){} try{ _voiceUI(false); }catch(e){} }
  var f=$('coachFab'), p=$('fabReview'), v=$('voiceFab');
  if(f) f.style.display = ai ? '' : 'none';
  if(p) p.style.display = (ai && !coachOpen) ? 'block' : 'none'; /* the pulse rides inside the AI Guide button; toggleCoach hides it while the panel is open */
  if(v) v.style.display = vo ? '' : 'none';
}
function setAiFeature(key, on){
  if(!canSetAiFeatures() || (key!=='aiGuide' && key!=='voice')) return;
  if(!data.settings) data.settings={aiGuide:false, voice:false};
  data.settings[key]=!!on;
  saveData();
  applyAiFeatures();
  render();
  if(currentModal==='org') renderOrgModal();
}
function aiFeaturesFold(){
  var st=data.settings||{};
  function sw(key, label, note){ return '<label class="ai-switch"><input type="checkbox" role="switch" id="aiSet_'+key+'"'+(st[key]?' checked':'')+' onchange="setAiFeature(\''+key+'\',this.checked)"/> <span>'+label+'</span></label><div class="ai-fold-note">'+note+'</div>'; }
  return '<details class="ai-fold" ontoggle="UI.aiFoldOpen=this.open"'+(UI.aiFoldOpen?' open':'')+'><summary>AI Features (off by default)</summary><div class="ai-fold-body">'
    + sw('aiGuide', 'AI Guide', 'When this is switched on, the AI Guide is live, and whatever users type here is sent to our AI provider.')
    + sw('voice', 'Voice', 'When this is on, Voice uses the browser\'s own speech recognition. Some browsers send the recording to the browser maker to turn it into text.')
    + '</div></details>';
}
function toggleCoach(){
if(!coachOpen && !aiGuideOn()) return; /* Part 2: blocks opening only, so the session seal and switching the setting off can always close it */
coachOpen=!coachOpen;
$('coachFab').className='coach-fab'+(coachOpen?' open':'');
$('fabReview').style.display=coachOpen?'none':'block';
$('coachPanel').className='coach-panel'+(coachOpen?' open':'');
if(coachOpen)renderCoachPanel();
}

function renderCoachPanel(){
var panel=$('coachPanel');if(!panel)return;
var ctx=currentStep?ctxLabel(currentStep):'Overview';
var h='<div class="coach-header"><div class="coach-header-title"><span>✦</span> Ask Danni</div><button class="coach-close" onclick="toggleCoach()">×</button></div>';
h+='<div class="coach-ai-notice">You are talking to an AI assistant. It can make mistakes, so check anything important.</div>'; /* Part 2 (A.2.6): "AI Guide" is a name, not a plain statement */
h+='<div style="padding:10px 24px;border-bottom:1px solid rgba(var(--fg-rgb),.06);background:rgba(var(--fg-rgb),.02);flex-shrink:0"><div style="font-family:var(--mono);font-size:12px;letter-spacing:.08em;color:var(--stone)">Context: '+esc(ctx)+'</div></div>';
h+='<div class="coach-msgs" id="coachMsgsEl">';
for(var i=0;i<coachMsgs.length;i++){var m=coachMsgs[i];
h+='<div class="coach-msg '+m.role+'"><div class="coach-sender">'+(m.role==='ai'?'Danni':'You')+'</div>'+esc(m.text)+'</div>'}
h+='</div>';
h+='<div class="coach-presets">';
var presets=['Where do I start?','Help with this step','What is CARE?','Explain LIT scoring','How does NIST map to this?'];
for(var i=0;i<presets.length;i++)h+='<button class="coach-preset" onclick="sendCoachPreset(\''+presets[i]+'\')">'+presets[i]+'</button>';
h+='</div>';
h+='<div class="coach-input-row"><textarea id="coachInput" placeholder="Ask about any step, concept, or challenge..." onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();sendCoach()}"></textarea><button class="coach-send" onclick="sendCoach()">→</button></div>';
panel.innerHTML=h;
var msgs=document.getElementById('coachMsgsEl');if(msgs)msgs.scrollTop=msgs.scrollHeight;
}

function sendCoachPreset(t){var inp=document.getElementById('coachInput');if(inp)inp.value=t;sendCoach();}

function sendCoach(){
if(!aiGuideOn()) return; /* Part 2: no request to the AI service */
var inp=document.getElementById('coachInput');if(!inp||!inp.value.trim())return;
var userText=inp.value.trim();inp.value='';
var thread=coachMsgs;/* Part S follow-up (7 Oct 2026): the reply belongs to the conversation it was asked in. sealSession replaces coachMsgs on a sign-out or change of organization, so a reply still in flight then lands in the old, discarded thread and never in the next organization's */
coachMsgs.push({role:'user',text:userText});
renderCoachPanel();
var ctx='User is working on: '+(currentStep?ctxLabel(currentStep)+' ('+currentPhase?.name+')':'the pipeline overview');

fetch(CLAUDE_API_URL,{method:'POST',headers:{'Content-Type':'application/json'},
body:JSON.stringify({
messages:[{role:'user',content:ctx+'\n\nUser question: '+userText}]})
}).then(function(r){return r.json()}).then(function(j){
var text='';if(j.content)for(var i=0;i<j.content.length;i++)if(j.content[i].text)text+=j.content[i].text;
if(!text)text='Could not generate response. Try again.';
thread.push({role:'ai',text:text});if(thread===coachMsgs)renderCoachPanel();
}).catch(function(){thread.push({role:'ai',text:'The AI Guide could not be reached. Please try again.'});if(thread===coachMsgs)renderCoachPanel()});
}


// === GROUP CHAT ===
var gchatOpen=false;
function chatArr(){if(!data.chatMsgs)data.chatMsgs=[];return data.chatMsgs}/* fix batch 1 item 6 (R-10, Spec §13, 20 Aug 2026): chat persists in the org blob; the demo thread is seed-owned; fresh organizations start empty */
var gchatUnreadCount=0;
var gchatSeenCount=null; function gchatRecount(){ var a=chatArr(); if(gchatSeenCount==null||gchatOpen){gchatSeenCount=a.length;gchatUnreadCount=0;return} var me=getCurrentUser(),n=0; for(var i=gchatSeenCount;i<a.length;i++){var m=a[i];var mine=!!m&&((m.by&&m.by===currentUserId)||(!m.by&&m.uid&&m.uid===currentUserId)||(!m.by&&!m.uid&&!!me&&m.name===me.name));if(m&&!mine)n++} gchatUnreadCount=n; } /* Sweep 4R item 5 (addendum 5 Oct 2026): the badge counts colleagues' messages since this session last saw the room; one's own never count */

/* copy-pass item 1 (21 Aug 2026, ruled by Paul): the chat carries real identities only — the member strip derives from the live roster and the simulated-reply machinery is gone (family form: persistent, real identity, no simulated replies). gchatColor survives for legacy who-coded messages (the seed thread). */
function gchatInitials(n){return String(n||'?').trim().split(/\s+/).map(function(w){return w.charAt(0)}).join('').toUpperCase().slice(0,2)||'?'}
function gchatMembers(){return (USERS||[]).map(function(u){return {id:u.id,initials:u.initials||gchatInitials(u.name||u.username),name:u.name||u.username||'Member',color:u.color||'#5a7fbc'}})}
function gchatColor(who){var map={F:'#C96838',H:'#5a7fbc',V:'#5c9e78',S:'#9b6fa8'};return map[who]||'#888'}

function toggleGChat(){
  if(SAMPLE_MODE && !gchatOpen) return; /* Part 3: Team Chat is off in the sample tab */
  gchatOpen=!gchatOpen;
  var navBtn=document.getElementById('gchatNavBtn');if(navBtn)navBtn.classList.toggle('nav-action-on',gchatOpen);
  var fab=document.getElementById('gchatFab');
  var panel=document.getElementById('gchatPanel');
  if(panel)panel.className='gchat-panel'+(gchatOpen?' open':'');
  if(gchatOpen){
    gchatUnreadCount=0; gchatSeenCount=chatArr().length; /* Sweep 4R item 5 */
    var u=document.getElementById('gchatUnread');
    if(u){u.style.display='none';u.textContent='0';}
    renderGChatPanel();
  }
}

function renderGChatPanel(){
  var panel=document.getElementById('gchatPanel');
  if(!panel)return;
  var _gm=gchatMembers();
  var avHtml='';
  for(var i=0;i<_gm.length&&i<4;i++){
    avHtml+='<div class="gchat-av" style="background:'+_gm[i].color+';color:#fff">'+esc(_gm[i].initials)+'</div>';
  }
  var memHtml='';
  for(var i=0;i<_gm.length;i++){
    var m=_gm[i];
    memHtml+='<div class="gchat-member"><div class="gchat-member-av" style="background:'+m.color+';color:#fff">'+m.initials+'</div>'+esc(m.name)+('')+'</div>';
  }
  var h='<div class="gchat-header"><div class="gchat-header-title"><div class="gchat-avatars">'+avHtml+'</div> Team Chat</div><button class="gchat-close" onclick="toggleGChat()">×</button></div>';
  h+='<div class="gchat-members">'+memHtml+'</div>';
  h+='<div class="gchat-msgs" id="gchatMsgsEl">';
  h+='<div class="gchat-day-div">Today</div>';
  var _cu=(typeof getCurrentUser==='function')&&getCurrentUser();
  var _cm=chatArr();for(var i=0;i<_cm.length;i++){
    var msg=_cm[i];
    var isMe=msg.uid?(!!_cu&&msg.uid===_cu.id):(msg.who==='F');
    var cls=isMe?'me':'them';
    var col=msg.color||gchatColor(msg.who);
    h+='<div class="gchat-msg '+cls+'">';
    h+='<div class="gchat-msg-av" style="background:'+col+';color:#fff">'+esc(msg.initials||msg.who||'?')+'</div>';
    h+='<div class="gchat-msg-body">';
    h+='<div class="gchat-msg-meta">'+esc(isMe?'You':msg.name)+' · '+msg.ts+'</div>';
    h+='<div class="gchat-msg-text">'+esc(msg.text)+'</div>';
    h+='</div></div>';
  }
  h+='</div>';
  h+='<div class="gchat-input-row"><textarea id="gchatInput" placeholder="Message the team..." onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();sendGChat()}"></textarea><button class="gchat-send" onclick="sendGChat()">→</button></div>';
  panel.innerHTML=h;
  var msgs=document.getElementById('gchatMsgsEl');
  if(msgs)msgs.scrollTop=msgs.scrollHeight;
}

function sendGChat(){
  var inp=document.getElementById('gchatInput');
  if(!inp||!inp.value.trim())return;
  var text=inp.value.trim();inp.value='';
  var now=new Date();
  var ts=(now.getHours()%12||12)+':'+(now.getMinutes()<10?'0':'')+now.getMinutes()+' '+(now.getHours()>=12?'PM':'AM');
  var _u=(typeof getCurrentUser==='function')&&getCurrentUser();
  chatArr().push({by:currentUserId,uid:_u&&_u.id,who:'F',name:(_u&&_u.name)||(_u&&_u.username)||'You',initials:_u?(_u.initials||gchatInitials(_u.name||_u.username)):'?',color:(_u&&_u.color)||'#C96838',ts:ts,text:text});saveData();/* copy-pass item 1 (21 Aug 2026): the send is the only push — real identity, no simulated replies */
  renderGChatPanel();
}
function ctxLabel(id){if(!id)return'';var i,j;for(i=0;i<PH.length;i++){for(j=0;j<PH[i].steps.length;j++)if(PH[i].steps[j].id===id)return'Step '+id+' \u00B7 '+PH[i].steps[j].name;for(j=0;j<(PH[i].outcomes||[]).length;j++)if(PH[i].outcomes[j].id===id)return'Outcome \u00B7 '+PH[i].outcomes[j].name}if(String(id).indexOf('sys-')===0){var sy=(data.systems||[]).find(function(x){return x&&x.id===id});if(sy)return'System \u00B7 '+(sy.name||id)}return'Step '+id}/* Sweep 4 round 3B items B25/B26 (24 Aug 2026): human-readable context labels for steps, outcomes, and systems */
function notesWhere(){
  if(currentPage==='step'&&currentStep){
    for(var i=0;i<PH.length;i++)for(var j=0;j<PH[i].steps.length;j++)
      if(PH[i].steps[j].id===currentStep)return'Step '+currentStep+' \u00B7 '+PH[i].steps[j].name;
    return ctxLabel(currentStep);
  }
  if(currentPage==='phase'&&currentStep){var ph=PH.find(function(p){return String(p.id)===String(currentStep)});if(ph)return'Phase '+ph.id+' \u00B7 '+ph.name}
  if(currentPage==='outcome'&&currentStep){for(var k=0;k<PH.length;k++){var o=(PH[k].outcomes||[]).find(function(x){return x.id===currentStep});if(o)return o.name}}
  if(currentPage==='system'&&currentStep){var sy=(data.systems||[]).find(function(x){return x.id===currentStep});if(sy)return sy.name}
  var map={home:'Home',learn:'Learn',insights:'Insights','mgmt-hub':'Track Program',phase5:'Dashboard',overview:'Program Overview',portfolio:'Risk Portfolio',pipeline:'Pipeline'};
  return map[currentPage]||'';
}
function goToNote(id){var x=(data.notes||[]).find(function(nn){return nn.id===id});if(!x||!x.page)return;
  if((x.page==='step'||x.page==='phase'||x.page==='outcome'||x.page==='system')&&x.step)go(x.page,x.step);else go(x.page)}
/* ── Item 58 (Spec §10 Rev R): open out-of-zone panels repaint on every render — foreign
   writes appear within one adoption cycle — and the focused field's value and caret
   survive the repaint. Governance adaptation of the ER form: coach panel included;
   the ER updateGChatUnread line has no Governance counterpart (unread paints via the
   nav badge on render). ── */
function repaintOpenPanels(){
  var a=document.activeElement,fid=a&&a.id,fv=(a&&fid&&('value' in a))?a.value:null;
  var fs=(a&&typeof a.selectionStart==='number')?a.selectionStart:null,fe2=(a&&typeof a.selectionEnd==='number')?a.selectionEnd:null;
  try{ if(notesOpen)renderNotesPanel(); }catch(e){}
  try{ if(gchatOpen)renderGChatPanel(); }catch(e){}
  try{ if(coachOpen)renderCoachPanel(); }catch(e){}
  try{ if(currentModal==='org')renderOrgModal(); }catch(e){}
  try{ if(currentModal==='assignments')renderAssignmentsModal(); }catch(e){}
  if(fid){try{var el2=document.getElementById(fid);if(el2&&el2!==a){if(fv!=null)el2.value=fv;el2.focus();if(fs!=null&&typeof el2.setSelectionRange==='function')el2.setSelectionRange(fs,fe2==null?fs:fe2)}}catch(e){}}
}
function toggleNotes(){
notesOpen=!notesOpen;
var fab=$('notesFab');if(fab)fab.className='notes-fab'+(notesOpen?' open':'');
var navBtn=document.getElementById('notesNavBtn');if(navBtn)navBtn.classList.toggle('nav-action-on',notesOpen);
var np=$('notesPanel');if(np)np.className='notes-panel'+(notesOpen?' open':'');
if(notesOpen)renderNotesPanel();
}

function updateNotesCount(){var el=$('notesCount');if(el){var n=(data.notes||[]).length;el.textContent=n;el.style.display=n?'':'none'}}

function renderNotesPanel(){
var panel=$('notesPanel');if(!panel)return;
var h='<div class="notes-header"><div class="notes-header-title">&#9998; Notes</div><button class="notes-close" onclick="toggleNotes()">×</button></div>';
h+='<div class="notes-list">';
var notes=data.notes||[];
if(!notes.length)h+='<div class="notes-empty">Capture insights as you work through the program.</div>';
else for(var i=notes.length-1;i>=0;i--){var n=notes[i];h+='<div class="note-card"><div class="note-text">'+esc(n.text)+'</div><div class="note-meta"><span class="note-date">'+(n.where&&n.id?'<span class="note-where" onclick="goToNote(\''+n.id+'\')" style="cursor:pointer;text-decoration:underline;text-underline-offset:2px" title="Jump to where this was captured">'+esc(n.where)+'</span> · ':(n.step?ctxLabel(n.step)+' · ':''))+fmt(n.createdAt)+'</span><button class="note-del" onclick="deleteNote(\''+n.id+'\')">×</button></div></div>'}
h+='</div>';
h+='<div class="notes-input-row"><textarea id="notesInput" placeholder="Write a note..." onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();addNote()}"></textarea><button class="notes-send" onclick="addNote()">&#9998;</button></div>';
panel.innerHTML=h;
}

function addNote(){var inp=document.getElementById('notesInput');if(!inp||!inp.value.trim())return;if(!data.notes)data.notes=[];data.notes.push({id:uid(),text:inp.value.trim(),page:currentPage,step:currentStep,where:notesWhere(),createdAt:Date.now()});saveData();renderNotesPanel();updateNotesCount();}
function deleteNote(id){data.notes=(data.notes||[]).filter(function(n){return n.id!==id});saveData();renderNotesPanel();updateNotesCount();}

